from __future__ import annotations

"""
Reusable Group 5 scalar crash/event measurement extractor.

Migrated from the validated historical Group 5 CSV/PDF pipeline.

Source policy:
    CSV exists -> CSV only
    CSV absent -> PDF

Supporting historical packages are used only for label/vocabulary support:
    Group 4 companion metadata -> CSV discovery support
    Frozen Group 5 CSV registry -> PDF vocabulary support

The original CSV/PDF remains authoritative.
No semantic normalization, unit conversion, or fuzzy event linking.
"""

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

GROUP_NAME = "group5"
RULE_VERSION = "2.2"


@dataclass
class Group5ExtractionResult:
    source_format: str
    source_path: str
    measurements: list[dict] = field(default_factory=list)
    values: list[dict] = field(default_factory=list)
    companion_context: list[dict] = field(default_factory=list)
    excluded: list[dict] = field(default_factory=list)
    unresolved: list[dict] = field(default_factory=list)
    issues: list[str] = field(default_factory=list)


def _make_ns(name: str, source: str):
    ns = {"__name__": f"_embedded_{name}"}
    exec(compile(source, f"<embedded:{name}>", "exec"), ns)
    return ns

_CSV_DISCOVERY_SOURCE = '"""\nDiscover Group 5 CSV candidates: non-time-series crash/event measurements.\n\nInputs\n------\ndata/processed/edr/group1_v4/report_index.csv\n\nOptional supporting handoff\n---------------------------\ndata/processed/edr/group4_final_v1/timeseries_companion_metadata.csv\n\nSource\n------\nOriginal CSV exports referenced by report_index.csv.\n\nOutput\n------\ndata/processed/edr/group5_csv_discovery_v1/\n\n    group5_candidate_fields.csv\n    group5_review_fields.csv\n    group5_report_coverage.csv\n    group5_label_summary.csv\n    group5_family_summary.csv\n    group5_section_summary.csv\n    errors.csv\n    metadata.json\n\nPurpose\n-------\nDiscover scalar / summary crash-event measurements that belong to Group 5.\n\nExamples include:\n- maximum/final Delta-V or recorded velocity-change summaries\n- longitudinal/lateral/resultant velocity-change summaries\n- time of maximum Delta-V / maximum recorded velocity change\n- peak acceleration\n- peak/max roll angle\n- peak/max angular rate\n- crash pulse / Delta-V duration or length\n- clipping time / accelerometer-range-exceeded timing\n- recorded side / crash direction / PDOF-like scalar fields\n\nImportant boundaries\n--------------------\nGroup 4:\n    repeated time-series rows remain excluded.\n\nGroup 3:\n    deployment command timing, restraint/occupant/deployment/status fields,\n    DTCs, warning lamps, etc. are not Group 5.\n\nGroup 6:\n    module configuration, technical identifiers, investigation fields, etc.\n    are not Group 5 unless a field is independently a crash measurement.\n\nThis is a DISCOVERY stage only:\n- no semantic normalization\n- no unit conversion\n- no event-identity inference\n- no source modification\n- no final structured extraction\n\nThe original CSV remains authoritative. Group 4 companion metadata is used\nonly as optional supporting evidence.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport re\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path, PureWindowsPath\n\n\ncsv.field_size_limit(100_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv_dict(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef read_raw_csv(path: Path):\n    rows = []\n\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        reader = csv.reader(f)\n\n        for index, row in enumerate(reader):\n            rows.append(\n                (\n                    index,\n                    [clean_cell(cell) for cell in row],\n                )\n            )\n\n    return rows\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef clean_cell(value):\n    text = str(\n        value\n        if value is not None\n        else ""\n    )\n\n    text = text.replace(\n        "\\r",\n        " ",\n    ).replace(\n        "\\n",\n        " ",\n    )\n\n    return re.sub(\n        r"\\s+",\n        " ",\n        text,\n    ).strip()\n\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        clean_cell(value),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode(\n            "utf-8"\n        )\n    ).hexdigest()[:24]\n\n\ndef populated(row):\n    return [\n        value\n        for value in row\n        if norm(value)\n    ]\n\n\ndef first_populated_with_index(row):\n    for index, value in enumerate(row):\n        value = norm(value)\n\n        if value:\n            return index, value\n\n    return None, ""\n\n\ndef looks_numeric(value):\n    text = norm(value)\n\n    if not text:\n        return False\n\n    text = text.replace(\n        ",",\n        "",\n    )\n\n    # Allow numeric source values with common unit suffixes.\n    text = re.sub(\n        r"\\s*(?:"\n        r"mph|km/h|kph|m/s|m/s\\^2|g|"\n        r"ms|msec|milliseconds?|"\n        r"sec|seconds?|"\n        r"deg|degrees?|deg/s|rad/s|"\n        r"%|percent"\n        r")\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef looks_value_like(value):\n    text = norm(value)\n\n    if not text:\n        return False\n\n    if looks_numeric(text):\n        return True\n\n    if text.casefold() in {\n        "n/a",\n        "na",\n        "sna",\n        "not available",\n        "data not available",\n        "unknown",\n        "invalid",\n    }:\n        return True\n\n    # Some direction/side scalar measurements are textual.\n    if re.fullmatch(\n        r"(?:"\n        r"left|right|front|rear|"\n        r"frontal|side|rollover|"\n        r"longitudinal|lateral|"\n        r"positive|negative"\n        r")",\n        text,\n        re.I,\n    ):\n        return True\n\n    return False\n\n\n# ============================================================\n# Source path resolution\n# ============================================================\n\ndef resolve_csv_path(\n    index_row: dict,\n    source_root: Path,\n):\n    raw = norm(\n        index_row.get(\n            "csv_path",\n            ""\n        )\n    )\n\n    if raw:\n        direct = Path(raw)\n\n        if direct.exists():\n            return direct\n\n        # On Windows this is usually already a valid path. This fallback\n        # also helps if the project was moved but the basename is unchanged.\n        basename = PureWindowsPath(\n            raw\n        ).name\n\n        case_id = norm(\n            index_row.get(\n                "case_id",\n                ""\n            )\n        )\n\n        if case_id and basename:\n            case_root = (\n                source_root\n                / case_id\n            )\n\n            if case_root.exists():\n                matches = list(\n                    case_root.rglob(\n                        basename\n                    )\n                )\n\n                if len(matches) == 1:\n                    return matches[0]\n\n                if len(matches) > 1:\n                    # Prefer cdr_exports.\n                    preferred = [\n                        path\n                        for path in matches\n                        if "cdr_exports"\n                        in str(path).casefold()\n                    ]\n\n                    if len(preferred) == 1:\n                        return preferred[0]\n\n                    return matches[0]\n\n    basename = norm(\n        index_row.get(\n            "export_basename",\n            ""\n        )\n    )\n\n    case_id = norm(\n        index_row.get(\n            "case_id",\n            ""\n        )\n    )\n\n    if basename and case_id:\n        case_root = (\n            source_root\n            / case_id\n        )\n\n        if case_root.exists():\n            matches = list(\n                case_root.rglob(\n                    basename + ".CSV"\n                )\n            )\n\n            if not matches:\n                matches = list(\n                    case_root.rglob(\n                        basename + ".csv"\n                    )\n                )\n\n            if matches:\n                return matches[0]\n\n    return None\n\n\n# ============================================================\n# Section-heading detection\n# ============================================================\n\ndef is_heading_row(row):\n    values = populated(row)\n\n    if len(values) != 1:\n        return False\n\n    text = values[0]\n\n    if not text:\n        return False\n\n    if looks_numeric(text):\n        return False\n\n    if len(text) > 220:\n        return False\n\n    # Common CDR headings are often uppercase, title-like, or end in DATA.\n    alpha = [\n        char\n        for char in text\n        if char.isalpha()\n    ]\n\n    if alpha:\n        uppercase_ratio = (\n            sum(\n                1\n                for char in alpha\n                if char.isupper()\n            )\n            / len(alpha)\n        )\n    else:\n        uppercase_ratio = 0.0\n\n    heading_terms = bool(\n        re.search(\n            r"\\b(?:"\n            r"data|status|summary|"\n            r"information|configuration|"\n            r"event|retrieval|deployment|"\n            r"non[- ]deployment|"\n            r"crash|rollover|"\n            r"delta[- ]?v|velocity change|"\n            r"system"\n            r")\\b",\n            text,\n            re.I,\n        )\n    )\n\n    return (\n        uppercase_ratio >= 0.70\n        or heading_terms\n    )\n\n\n# ============================================================\n# Event hint extraction\n# ============================================================\n\nEVENT_PATTERNS = [\n    r"\\bevent record\\s*#?\\s*\\d+\\b",\n    r"\\bevent\\s*#\\s*\\d+\\b",\n    r"\\bdeployment event\\s*#?\\s*\\d*\\b",\n    r"\\bnon[- ]deployment event\\b",\n    r"\\bmost recent event\\b",\n    r"\\b\\d+(?:st|nd|rd|th)\\s+prior event\\b",\n    r"\\btrg\\s*\\d+\\b",\n]\n\n\ndef extract_event_hint(*texts):\n    combined = " | ".join(\n        norm(text)\n        for text in texts\n        if norm(text)\n    )\n\n    hints = []\n\n    for pattern in EVENT_PATTERNS:\n        for match in re.findall(\n            pattern,\n            combined,\n            flags=re.I,\n        ):\n            cleaned = norm(match)\n\n            if cleaned.casefold() not in {\n                item.casefold()\n                for item in hints\n            }:\n                hints.append(\n                    cleaned\n                )\n\n    return " | ".join(hints)\n\n\n# ============================================================\n# Group 5 family rules\n# ============================================================\n\nFAMILY_RULES = [\n    (\n        "delta_v_summary",\n        [\n            r"\\bmaximum\\b.*\\bdelta[- ]?v\\b",\n            r"\\bmax(?:imum)?\\b.*\\bvelocity change\\b",\n            r"\\bmaximum\\b.*\\brecorded vehicle velocity change\\b",\n            r"\\bmaximum\\b.*\\brecorded velocity change\\b",\n            r"\\bfinal\\b.*\\bdelta[- ]?v\\b",\n            r"\\bfinal\\b.*\\bvelocity change\\b",\n            r"\\bresultant\\b.*\\bdelta[- ]?v\\b",\n            r"\\bresultant\\b.*\\bvelocity change\\b",\n            r"\\blongitudinal\\b.*\\bvelocity change\\b",\n            r"\\blateral\\b.*\\bvelocity change\\b",\n            r"\\blongitudinal\\b.*\\bdelta[- ]?v\\b",\n            r"\\blateral\\b.*\\bdelta[- ]?v\\b",\n        ],\n    ),\n    (\n        "delta_v_timing",\n        [\n            r"\\btime\\b.*\\bmaximum\\b.*\\bdelta[- ]?v\\b",\n            r"\\btime\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\balgorithm enable\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\btime from algorithm enable\\b.*\\bmaximum\\b",\n            r"\\btime\\b.*\\bmax(?:imum)?\\b.*\\brecorded velocity change\\b",\n            r"\\btime\\b.*\\bmax(?:imum)?\\b.*\\brecorded vehicle velocity change\\b",\n        ],\n    ),\n    (\n        "acceleration_summary",\n        [\n            r"\\b(?:maximum|max|peak)\\b.*\\bacceleration\\b",\n            r"\\bacceleration\\b.*\\b(?:maximum|max|peak)\\b",\n            r"\\bpeak\\b.*\\bg\\b",\n        ],\n    ),\n    (\n        "roll_summary",\n        [\n            r"\\b(?:maximum|max|peak)\\b.*\\broll angle\\b",\n            r"\\broll angle\\b.*\\b(?:maximum|max|peak)\\b",\n            r"\\brollangle peak\\b",\n        ],\n    ),\n    (\n        "angular_rate_summary",\n        [\n            r"\\b(?:maximum|max|peak)\\b.*\\b(?:angular rate|yaw rate|roll rate)\\b",\n            r"\\b(?:angular rate|yaw rate|roll rate)\\b.*\\b(?:maximum|max|peak)\\b",\n        ],\n    ),\n    (\n        "duration_length",\n        [\n            r"\\blength of\\b.*\\bdelta[- ]?v\\b",\n            r"\\bduration\\b.*\\bdelta[- ]?v\\b",\n            r"\\bduration\\b.*\\bcrash pulse\\b",\n            r"\\bcrash pulse\\b.*\\bduration\\b",\n            r"\\bdelta[- ]?v\\b.*\\bduration\\b",\n        ],\n    ),\n    (\n        "range_clipping_timing",\n        [\n            r"\\bclipping time\\b",\n            r"\\baccelerometer range exceeded\\b",\n            r"\\btime\\b.*\\baccelerometer\\b.*\\brange exceeded\\b",\n        ],\n    ),\n    (\n        "direction_summary",\n        [\n            r"\\bpdof\\b",\n            r"\\bprincipal direction of force\\b",\n            r"\\bcrash direction\\b",\n            r"\\brecorded direction\\b",\n            r"\\brecorded side\\b",\n            r"\\bprincipal direction\\b",\n        ],\n    ),\n    (\n        "trigger_relative_timing",\n        [\n            r"\\btime from time zero to trg\\b",\n            r"\\btime zero\\b.*\\btrg\\b",\n            r"\\btime\\b.*\\btrigger\\b",\n        ],\n    ),\n]\n\n\ndef classify_family(label):\n    text = norm(label)\n\n    for family, patterns in FAMILY_RULES:\n        if any(\n            re.search(\n                pattern,\n                text,\n                re.I,\n            )\n            for pattern in patterns\n        ):\n            return family\n\n    return ""\n\n\n# ============================================================\n# Strong Group 3 / Group 2 / Group 6 exclusions\n# ============================================================\n\nGROUP3_PATTERNS = [\n    r"\\bair ?bag\\b",\n    r"\\bpretensioner\\b",\n    r"\\bdeployment command\\b",\n    r"\\bdeployment criteria\\b",\n    r"\\b1st stage\\b",\n    r"\\b2nd stage\\b",\n    r"\\bbelt switch\\b",\n    r"\\bseat belt\\b",\n    r"\\boccupant\\b",\n    r"\\bpassenger classification\\b",\n    r"\\bsuppression\\b",\n    r"\\bwarning lamp\\b",\n    r"\\bsir\\b",\n    r"\\bdtc\\b",\n    r"\\bdiagnostic trouble\\b",\n    r"\\bseat position\\b",\n    r"\\brestraint\\b",\n]\n\nGROUP2_PATTERNS = [\n    r"\\bevent recording complete\\b",\n    r"\\bcrash record locked\\b",\n    r"\\brecording complete\\b",\n    r"\\bmultiple events?\\b",\n    r"\\bevent counter\\b",\n    r"\\brecord status\\b",\n    r"\\bretrieval status\\b",\n    r"\\bassociated events?\\b",\n    r"\\bevents? not recorded\\b",\n]\n\nGROUP6_PATTERNS = [\n    r"\\bignition cycles?\\b",\n    r"\\bpart number\\b",\n    r"\\bserial number\\b",\n    r"\\bsoftware version\\b",\n    r"\\bmodule\\b",\n    r"\\bconfiguration\\b",\n    r"\\bconfigured for\\b",\n    r"\\bdownload\\b",\n    r"\\binvestigation\\b",\n    r"\\bvin\\b",\n    r"\\bvehicle identification number\\b",\n]\n\nGROUP1_PATTERNS = [\n    r"\\bfilename\\b",\n    r"\\bimaged with\\b",\n    r"\\breported with\\b",\n    r"\\bcrash date\\b",\n    r"\\bedr data imaging date\\b",\n    r"\\buser entered vin\\b",\n    r"\\bdevice type\\b",\n]\n\n\ndef matches_any(\n    text,\n    patterns,\n):\n    return any(\n        re.search(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern in patterns\n    )\n\n\n# ============================================================\n# Time-series exclusion\n# ============================================================\n\nTIMESERIES_AXIS_PATTERNS = [\n    r"^\\s*time\\s*(?:\\([^)]*\\))?\\s*$",\n    r"^\\s*times\\s*(?:\\([^)]*\\))?\\s*$",\n    r"^\\s*seconds?\\s+before\\b",\n    r"^\\s*seconds?\\s+after\\b",\n    r"^\\s*sample\\s+count\\b",\n    r"^\\s*buffer address\\b",\n]\n\n\ndef looks_like_timeseries_axis(label):\n    text = norm(label)\n\n    return any(\n        re.search(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern in TIMESERIES_AXIS_PATTERNS\n    )\n\n\n# ============================================================\n# Group 4 companion handoff support\n# ============================================================\n\ndef load_companion_label_support(path: Path):\n    """\n    Build a normalized-label support set from Group 4 companion metadata.\n    This is supporting evidence only.\n    """\n\n    support = Counter()\n\n    if not path.exists():\n        return support\n\n    rows = read_csv_dict(path)\n\n    for row in rows:\n        raw_json = row.get(\n            "source_rows_json",\n            "",\n        )\n\n        if raw_json:\n            try:\n                source_rows = json.loads(\n                    raw_json\n                )\n            except (\n                json.JSONDecodeError,\n                TypeError,\n            ):\n                source_rows = []\n\n            if isinstance(\n                source_rows,\n                list,\n            ):\n                for source_row in source_rows:\n                    if not isinstance(\n                        source_row,\n                        list,\n                    ):\n                        continue\n\n                    _, label = (\n                        first_populated_with_index(\n                            source_row\n                        )\n                    )\n\n                    key = norm_key(label)\n\n                    if key:\n                        support[key] += 1\n\n        for field in (\n            "source_heading_hint",\n            "source_heading",\n        ):\n            key = norm_key(\n                row.get(\n                    field,\n                    ""\n                )\n            )\n\n            if key:\n                support[key] += 1\n\n    return support\n\n\n# ============================================================\n# Candidate scoring\n# ============================================================\n\ndef score_field(\n    label,\n    value,\n    section_heading,\n    companion_support,\n):\n    label_text = norm(label)\n    section_text = norm(\n        section_heading\n    )\n\n    combined = (\n        label_text\n        + " | "\n        + section_text\n    )\n\n    family = classify_family(\n        label_text\n    )\n\n    score = 0\n    evidence = []\n    exclusions = []\n\n    # --------------------------------------------------------\n    # Strong positive family evidence\n    # --------------------------------------------------------\n\n    if family:\n        if family in {\n            "delta_v_summary",\n            "delta_v_timing",\n            "acceleration_summary",\n            "roll_summary",\n            "angular_rate_summary",\n            "direction_summary",\n        }:\n            score += 6\n        else:\n            score += 5\n\n        evidence.append(\n            f"family:{family}"\n        )\n\n    # Generic crash-measurement cues.\n    if re.search(\n        r"\\b(?:"\n        r"maximum|max|peak|final|"\n        r"resultant|velocity change|"\n        r"delta[- ]?v|acceleration|"\n        r"roll angle|angular rate|"\n        r"yaw rate|roll rate|"\n        r"clipping|recorded side|pdof"\n        r")\\b",\n        label_text,\n        re.I,\n    ):\n        score += 1\n        evidence.append(\n            "crash_measurement_terms"\n        )\n\n    # Scalar-like value.\n    if looks_value_like(\n        value\n    ):\n        score += 1\n        evidence.append(\n            "scalar_value_like"\n        )\n\n    # Event/crash context can modestly support a candidate.\n    if re.search(\n        r"\\b(?:"\n        r"crash|event|deployment|"\n        r"non[- ]deployment|"\n        r"delta[- ]?v|velocity change"\n        r")\\b",\n        section_text,\n        re.I,\n    ):\n        score += 1\n        evidence.append(\n            "event_or_crash_section_context"\n        )\n\n    # Optional Group 4 handoff support.\n    support_count = companion_support.get(\n        norm_key(\n            label_text\n        ),\n        0,\n    )\n\n    if support_count:\n        score += 2\n        evidence.append(\n            "group4_companion_handoff_support"\n        )\n\n    # --------------------------------------------------------\n    # Strong exclusions\n    # --------------------------------------------------------\n\n    if looks_like_timeseries_axis(\n        label_text\n    ):\n        exclusions.append(\n            "group4_timeseries_axis"\n        )\n\n    if matches_any(\n        label_text,\n        GROUP3_PATTERNS,\n    ):\n        # Do not exclude a true Delta-V summary merely because a broad\n        # section happens to say Deployment. Exclusion is label-based.\n        exclusions.append(\n            "group3_deployment_status"\n        )\n\n    if matches_any(\n        label_text,\n        GROUP2_PATTERNS,\n    ):\n        exclusions.append(\n            "group2_record_structure"\n        )\n\n    if matches_any(\n        label_text,\n        GROUP6_PATTERNS,\n    ):\n        exclusions.append(\n            "group6_technical_or_investigation"\n        )\n\n    if matches_any(\n        label_text,\n        GROUP1_PATTERNS,\n    ):\n        exclusions.append(\n            "group1_report_metadata"\n        )\n\n    # Explicit deployment timing is Group 3, even though it contains "time".\n    if re.search(\n        r"\\btime\\b.*\\bdeployment\\b",\n        label_text,\n        re.I,\n    ) and not re.search(\n        r"\\bmaximum\\b.*\\bvelocity change\\b",\n        label_text,\n        re.I,\n    ):\n        if (\n            "group3_deployment_status"\n            not in exclusions\n        ):\n            exclusions.append(\n                "group3_deployment_status"\n            )\n\n    # Event-to-event timing is structural/contextual rather than a crash\n    # dynamic measurement for this extraction grouping.\n    if re.search(\n        r"\\btime between\\b.*\\bevents?\\b",\n        label_text,\n        re.I,\n    ):\n        exclusions.append(\n            "group2_event_relationship_timing"\n        )\n\n    # --------------------------------------------------------\n    # Decision\n    # --------------------------------------------------------\n\n    if exclusions:\n        decision = "excluded_overlap"\n\n    elif score >= 6:\n        decision = "candidate"\n\n    elif score >= 3:\n        decision = "review"\n\n    else:\n        decision = "not_group5"\n\n    return {\n        "family":\n            family\n            or "other_crash_measurement",\n\n        "score":\n            score,\n\n        "decision":\n            decision,\n\n        "evidence":\n            evidence,\n\n        "exclusions":\n            exclusions,\n\n        "group4_companion_support_count":\n            support_count,\n    }\n\n\n# ============================================================\n# Parse scalar-like observations\n# ============================================================\n\ndef parse_scalar_observation(\n    row,\n):\n    """\n    Return (label, value, value_column_index) for a likely field-value row.\n\n    Discovery is intentionally conservative:\n    - at least two populated cells\n    - first populated cell must be textual\n    - later rows of obvious numeric time-series are rejected elsewhere\n    """\n\n    nonblank = [\n        (\n            index,\n            norm(value),\n        )\n        for index, value in enumerate(\n            row\n        )\n        if norm(value)\n    ]\n\n    if len(nonblank) < 2:\n        return None\n\n    label_index, label = (\n        nonblank[0]\n    )\n\n    if looks_numeric(\n        label\n    ):\n        return None\n\n    # For ordinary scalar rows, the next populated cell is usually the value.\n    # If there are only a few cells, use the last populated cell because some\n    # layouts include a separate unit/middle column.\n    if len(nonblank) <= 4:\n        value_index, value = (\n            nonblank[-1]\n        )\n    else:\n        # Very wide rows are more likely tables/time-series than scalars.\n        return None\n\n    if value_index == label_index:\n        return None\n\n    return {\n        "label_index":\n            label_index,\n\n        "label":\n            label,\n\n        "value_index":\n            value_index,\n\n        "value":\n            value,\n\n        "populated_cell_count":\n            len(nonblank),\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--report-index",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group1_v4/report_index.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--source-root",\n        type=Path,\n        default=Path(\n            "data/temp"\n        ),\n    )\n\n    parser.add_argument(\n        "--group4-companion",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_final_v1/"\n            "timeseries_companion_metadata.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_discovery_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    if not args.report_index.exists():\n        raise FileNotFoundError(\n            args.report_index\n        )\n\n    report_index = read_csv_dict(\n        args.report_index\n    )\n\n    companion_support = (\n        load_companion_label_support(\n            args.group4_companion\n        )\n    )\n\n    out = args.output_directory\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    candidates = []\n    reviews = []\n    excluded_overlap = []\n\n    coverage = []\n    errors = []\n\n    label_counter = Counter()\n    family_counter = Counter()\n    section_counter = Counter()\n    decision_counter = Counter()\n\n    csv_selected = 0\n    csv_processed = 0\n    reports_with_candidates = set()\n    reports_with_reviews = set()\n\n    for report_number, index_row in enumerate(\n        report_index,\n        1,\n    ):\n\n        csv_status = norm(\n            index_row.get(\n                "csv_status",\n                ""\n            )\n        ).casefold()\n\n        csv_path_text = norm(\n            index_row.get(\n                "csv_path",\n                ""\n            )\n        )\n\n        # Select reports that appear to have an available CSV.\n        if (\n            not csv_path_text\n            or csv_status\n            in {\n                "",\n                "not_available",\n                "missing",\n                "none",\n            }\n        ):\n            continue\n\n        csv_selected += 1\n\n        csv_path = resolve_csv_path(\n            index_row,\n            args.source_root,\n        )\n\n        if (\n            csv_path is None\n            or not csv_path.exists()\n        ):\n            errors.append({\n                **{\n                    key:\n                        index_row.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "error_type":\n                    "csv_source_not_found",\n\n                "csv_path":\n                    csv_path_text,\n\n                "error":\n                    "Could not resolve CSV source path.",\n            })\n\n            coverage.append({\n                **{\n                    key:\n                        index_row.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "csv_path":\n                    csv_path_text,\n\n                "processing_status":\n                    "source_not_found",\n\n                "candidate_count":\n                    0,\n\n                "review_count":\n                    0,\n\n                "excluded_overlap_count":\n                    0,\n            })\n\n            continue\n\n        try:\n            rows = read_raw_csv(\n                csv_path\n            )\n\n        except Exception as exc:\n            errors.append({\n                **{\n                    key:\n                        index_row.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "error_type":\n                    type(exc).__name__,\n\n                "csv_path":\n                    str(csv_path),\n\n                "error":\n                    str(exc),\n            })\n\n            coverage.append({\n                **{\n                    key:\n                        index_row.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "csv_path":\n                    str(csv_path),\n\n                "processing_status":\n                    "source_error",\n\n                "candidate_count":\n                    0,\n\n                "review_count":\n                    0,\n\n                "excluded_overlap_count":\n                    0,\n            })\n\n            continue\n\n        csv_processed += 1\n\n        current_section = ""\n\n        report_candidates = 0\n        report_reviews = 0\n        report_excluded = 0\n\n        for row_index, row in rows:\n\n            if is_heading_row(\n                row\n            ):\n                current_section = (\n                    populated(row)[0]\n                )\n                continue\n\n            parsed = parse_scalar_observation(\n                row\n            )\n\n            if parsed is None:\n                continue\n\n            label = parsed[\n                "label"\n            ]\n\n            value = parsed[\n                "value"\n            ]\n\n            # Very common time-series/data-table headers should not enter\n            # scalar discovery even if they are only two cells wide.\n            if looks_like_timeseries_axis(\n                label\n            ):\n                continue\n\n            result = score_field(\n                label=label,\n                value=value,\n                section_heading=current_section,\n                companion_support=companion_support,\n            )\n\n            if result[\n                "decision"\n            ] == "not_group5":\n                continue\n\n            event_hint = extract_event_hint(\n                current_section,\n                label,\n            )\n\n            candidate_id = (\n                "g5csv_"\n                + identifier(\n                    index_row.get(\n                        "report_id",\n                        ""\n                    ),\n                    row_index,\n                    label,\n                    value,\n                )\n            )\n\n            observation = {\n                **{\n                    key:\n                        index_row.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "group5_candidate_id":\n                    candidate_id,\n\n                "source_format":\n                    "csv",\n\n                "source_path":\n                    str(csv_path),\n\n                "source_record_index":\n                    row_index,\n\n                "source_section_heading":\n                    current_section,\n\n                "event_hint":\n                    event_hint,\n\n                "field_label_raw":\n                    label,\n\n                "field_value_raw":\n                    value,\n\n                "value_column_index":\n                    parsed[\n                        "value_index"\n                    ],\n\n                "populated_cell_count":\n                    parsed[\n                        "populated_cell_count"\n                    ],\n\n                "source_row_json":\n                    json.dumps(\n                        row,\n                        ensure_ascii=False,\n                    ),\n\n                "candidate_family":\n                    result[\n                        "family"\n                    ],\n\n                "candidate_score":\n                    result[\n                        "score"\n                    ],\n\n                "discovery_decision":\n                    result[\n                        "decision"\n                    ],\n\n                "evidence_json":\n                    json.dumps(\n                        result[\n                            "evidence"\n                        ],\n                        ensure_ascii=False,\n                    ),\n\n                "overlap_exclusions_json":\n                    json.dumps(\n                        result[\n                            "exclusions"\n                        ],\n                        ensure_ascii=False,\n                    ),\n\n                "group4_companion_support_count":\n                    result[\n                        "group4_companion_support_count"\n                    ],\n\n                "semantic_normalization_status":\n                    "not_normalized",\n\n                "unit_conversion_status":\n                    "not_converted",\n\n                "event_link_status":\n                    (\n                        "source_hint_only"\n                        if event_hint\n                        else "not_linked"\n                    ),\n            }\n\n            decision_counter[\n                result[\n                    "decision"\n                ]\n            ] += 1\n\n            if result[\n                "decision"\n            ] == "candidate":\n\n                candidates.append(\n                    observation\n                )\n\n                report_candidates += 1\n\n                reports_with_candidates.add(\n                    index_row.get(\n                        "report_id",\n                        ""\n                    )\n                )\n\n                label_counter[\n                    norm_key(label)\n                ] += 1\n\n                family_counter[\n                    result[\n                        "family"\n                    ]\n                ] += 1\n\n                section_counter[\n                    norm(\n                        current_section\n                    )\n                    or "<no_section_heading>"\n                ] += 1\n\n            elif result[\n                "decision"\n            ] == "review":\n\n                reviews.append(\n                    observation\n                )\n\n                report_reviews += 1\n\n                reports_with_reviews.add(\n                    index_row.get(\n                        "report_id",\n                        ""\n                    )\n                )\n\n            elif result[\n                "decision"\n            ] == "excluded_overlap":\n\n                excluded_overlap.append(\n                    observation\n                )\n\n                report_excluded += 1\n\n        if report_candidates:\n            status = (\n                "group5_candidates_found"\n            )\n\n        elif report_reviews:\n            status = (\n                "review_only"\n            )\n\n        else:\n            status = (\n                "no_group5_candidates"\n            )\n\n        coverage.append({\n            **{\n                key:\n                    index_row.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "csv_path":\n                str(csv_path),\n\n            "processing_status":\n                status,\n\n            "candidate_count":\n                report_candidates,\n\n            "review_count":\n                report_reviews,\n\n            "excluded_overlap_count":\n                report_excluded,\n        })\n\n        if (\n            csv_processed % 100 == 0\n            or csv_processed\n            == csv_selected\n        ):\n            print(\n                "Discovered Group 5 CSV "\n                f"{csv_processed}/"\n                f"{csv_selected} reports...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    label_summary = []\n\n    raw_label_examples = defaultdict(\n        Counter\n    )\n\n    for row in candidates:\n        key = norm_key(\n            row[\n                "field_label_raw"\n            ]\n        )\n\n        raw_label_examples[\n            key\n        ][\n            row[\n                "field_label_raw"\n            ]\n        ] += 1\n\n    for key, count in (\n        label_counter.most_common()\n    ):\n        examples = [\n            label\n            for label, _\n            in raw_label_examples[\n                key\n            ].most_common(\n                5\n            )\n        ]\n\n        label_summary.append({\n            "normalized_label":\n                key,\n\n            "candidate_count":\n                count,\n\n            "raw_label_examples_json":\n                json.dumps(\n                    examples,\n                    ensure_ascii=False,\n                ),\n        })\n\n    family_summary = [\n        {\n            "candidate_family":\n                family,\n\n            "candidate_count":\n                count,\n        }\n        for family, count\n        in family_counter.most_common()\n    ]\n\n    section_summary = [\n        {\n            "source_section_heading":\n                section,\n\n            "candidate_count":\n                count,\n        }\n        for section, count\n        in section_counter.most_common()\n    ]\n\n    # ========================================================\n    # Output\n    # ========================================================\n\n    candidate_columns = [\n        *BASE,\n        "group5_candidate_id",\n        "source_format",\n        "source_path",\n        "source_record_index",\n        "source_section_heading",\n        "event_hint",\n        "field_label_raw",\n        "field_value_raw",\n        "value_column_index",\n        "populated_cell_count",\n        "source_row_json",\n        "candidate_family",\n        "candidate_score",\n        "discovery_decision",\n        "evidence_json",\n        "overlap_exclusions_json",\n        "group4_companion_support_count",\n        "semantic_normalization_status",\n        "unit_conversion_status",\n        "event_link_status",\n    ]\n\n    write_csv(\n        out\n        / "group5_candidate_fields.csv",\n        candidates,\n        candidate_columns,\n    )\n\n    write_csv(\n        out\n        / "group5_review_fields.csv",\n        reviews,\n        candidate_columns,\n    )\n\n    # Keep excluded overlap evidence because it will help us refine Group 3/6\n    # routing later, but it is not part of the Group 5 candidate population.\n    write_csv(\n        out\n        / "group5_excluded_overlap_fields.csv",\n        excluded_overlap,\n        candidate_columns,\n    )\n\n    write_csv(\n        out\n        / "group5_report_coverage.csv",\n        coverage,\n        [\n            *BASE,\n            "csv_path",\n            "processing_status",\n            "candidate_count",\n            "review_count",\n            "excluded_overlap_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_label_summary.csv",\n        label_summary,\n        [\n            "normalized_label",\n            "candidate_count",\n            "raw_label_examples_json",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_family_summary.csv",\n        family_summary,\n        [\n            "candidate_family",\n            "candidate_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_section_summary.csv",\n        section_summary,\n        [\n            "source_section_heading",\n            "candidate_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "errors.csv",\n        errors,\n        [\n            *BASE,\n            "error_type",\n            "csv_path",\n            "error",\n        ],\n    )\n\n    coverage_counts = Counter(\n        row[\n            "processing_status"\n        ]\n        for row in coverage\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "CSV discovery",\n\n        "reports_in_index":\n            len(\n                report_index\n            ),\n\n        "csv_reports_selected":\n            csv_selected,\n\n        "csv_reports_processed":\n            csv_processed,\n\n        "reports_with_group5_candidates":\n            len(\n                reports_with_candidates\n            ),\n\n        "reports_with_review_only_or_review_fields":\n            len(\n                reports_with_reviews\n            ),\n\n        "candidate_field_count":\n            len(\n                candidates\n            ),\n\n        "review_field_count":\n            len(\n                reviews\n            ),\n\n        "excluded_overlap_field_count":\n            len(\n                excluded_overlap\n            ),\n\n        "candidate_family_counts":\n            dict(\n                family_counter\n            ),\n\n        "decision_counts":\n            dict(\n                decision_counter\n            ),\n\n        "coverage_status_counts":\n            dict(\n                coverage_counts\n            ),\n\n        "unique_candidate_labels":\n            len(\n                label_counter\n            ),\n\n        "group4_companion_handoff_available":\n            args.group4_companion.exists(),\n\n        "group4_companion_support_label_count":\n            len(\n                companion_support\n            ),\n\n        "source_errors":\n            len(\n                errors\n            ),\n\n        "scope":\n            (\n                "CSV-first discovery for Group 5 scalar/non-time-series "\n                "crash and event measurements. Original CSV exports are "\n                "authoritative. Group 4 companion metadata is used only "\n                "as optional supporting evidence. Candidate families "\n                "include Delta-V/velocity-change summaries, timing of "\n                "maximum velocity change, peak acceleration, roll and "\n                "angular summaries, duration/length fields, clipping or "\n                "accelerometer-range timing, recorded side/direction, "\n                "and similar scalar crash-dynamics measurements. "\n                "Repeated temporal structures remain Group 4. "\n                "Deployment/restraint/status fields are excluded toward "\n                "Group 3; record-structure fields toward Group 2; "\n                "technical/investigation fields toward Group 6. "\n                "No semantic normalization, unit conversion, event "\n                "identity inference, PDF processing, or final extraction "\n                "is performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 5 CSV DISCOVERY COMPLETE."\n    )\n\n\n'

_CSV_AUDIT_SOURCE = '"""\nAudit Group 5 CSV discovery results.\n\nInputs\n------\ndata/processed/edr/group5_csv_discovery_v1/\n    group5_candidate_fields.csv\n    group5_review_fields.csv\n\nOutputs\n-------\ndata/processed/edr/group5_csv_audit_v1/\n\n    accepted_group5_fields.csv\n    companion_group5_context.csv\n    excluded_non_group5_fields.csv\n    remaining_review_fields.csv\n    audit_all_fields.csv\n    family_summary.csv\n    decision_summary.csv\n    label_decision_summary.csv\n    metadata.json\n\nPurpose\n-------\nRefine Group 5 discovery before structured extraction.\n\nKey corrections\n---------------\n1. Split true Delta-V / velocity-change scalar values from timing fields.\n2. Split peak acceleration values from time-of-peak acceleration.\n3. Keep clipping/range-exceeded timing as Group 5 measurement-quality timing.\n4. Recover selected Group 5 measurements from the first-stage review set.\n5. Route scalar context/status that describes a Group 5 measurement to\n   companion metadata rather than treating it as a core measurement.\n6. Keep unrelated restraint/deployment/status/record/configuration fields\n   outside Group 5.\n\nThis is still an audit stage:\n- no semantic normalization of values\n- no unit conversion\n- no fuzzy event identity inference\n- no PDF processing\n- original raw labels/values/provenance are preserved\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\ndef union_columns(rows):\n    seen = set()\n    columns = []\n\n    preferred = [\n        "report_id",\n        "case_id",\n        "vehicle_number",\n        "export_basename",\n        "group5_candidate_id",\n        "source_format",\n        "source_path",\n        "source_record_index",\n        "source_section_heading",\n        "event_hint",\n        "field_label_raw",\n        "field_value_raw",\n        "candidate_family",\n        "audited_family",\n        "audit_decision",\n        "audit_status",\n        "audit_reason",\n    ]\n\n    for column in preferred:\n        if column not in seen:\n            seen.add(column)\n            columns.append(column)\n\n    for row in rows:\n        for key in row.keys():\n            if key not in seen:\n                seen.add(key)\n                columns.append(key)\n\n    return columns\n\n\n# ============================================================\n# Helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef matches(text, pattern):\n    return bool(\n        re.search(\n            pattern,\n            norm(text),\n            re.I,\n        )\n    )\n\n\n# ============================================================\n# Family refinement for discovery candidates\n# ============================================================\n\ndef refine_candidate_family(label, old_family):\n    text = norm(label)\n\n    # --------------------------------------------------------\n    # Measurement-quality timing first\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\b(?:"\n        r"clipping time|"\n        r"accelerometer range exceeded|"\n        r"sensor design range (?:was )?exceeded|"\n        r"reached maximum sensor range"\n        r")\\b",\n    ):\n        return "range_clipping_timing"\n\n    # --------------------------------------------------------\n    # Acceleration peak/timing\n    # --------------------------------------------------------\n\n    if (\n        matches(\n            text,\n            r"\\btime\\b",\n        )\n        and matches(\n            text,\n            r"\\bmaximum acceleration\\b",\n        )\n    ):\n        return "acceleration_peak_timing"\n\n    if matches(\n        text,\n        r"\\bmaximum acceleration\\b",\n    ):\n        return "acceleration_peak"\n\n    # --------------------------------------------------------\n    # Delta-V timing\n    # --------------------------------------------------------\n\n    if (\n        matches(\n            text,\n            r"\\b(?:"\n            r"time|"\n            r"time to|"\n            r"time from"\n            r")\\b",\n        )\n        and matches(\n            text,\n            r"\\b(?:"\n            r"delta[- ]?v|"\n            r"velocity change|"\n            r"synthesis delta[- ]?v"\n            r")\\b",\n        )\n        and matches(\n            text,\n            r"\\b(?:"\n            r"maximum|max(?:imum)?|"\n            r"recorded"\n            r")\\b",\n        )\n    ):\n        return "delta_v_timing"\n\n    # --------------------------------------------------------\n    # Delta-V time-zero offsets\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\bdelta[- ]?v\\b.*\\btime zero offset\\b",\n    ):\n        return "delta_v_time_zero_offset"\n\n    # --------------------------------------------------------\n    # Delta-V duration / integration\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\blength of delta[- ]?v\\b",\n    ):\n        return "delta_v_duration"\n\n    if matches(\n        text,\n        r"\\bintegration time\\b.*\\bdelta[- ]?v\\b",\n    ):\n        return "delta_v_integration_time"\n\n    # --------------------------------------------------------\n    # Delta-V component / maximum summaries\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\b(?:"\n        r"maximum|max\\.?|max"\n        r")\\b.*\\b(?:"\n        r"delta[- ]?v|"\n        r"velocity change"\n        r")\\b",\n    ):\n        return "delta_v_summary"\n\n    if matches(\n        text,\n        r"\\b(?:"\n        r"longitudinal|lateral"\n        r")\\b.*\\bvelocity change\\b.*\\btime of maximum\\b",\n    ):\n        return "delta_v_component_at_maximum"\n\n    if matches(\n        text,\n        r"\\b(?:resultant|synthesis)\\b.*\\bdelta[- ]?v\\b",\n    ):\n        return "delta_v_summary"\n\n    # --------------------------------------------------------\n    # Roll / direction\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\broll ?angle peak\\b|\\brollangle peak\\b",\n    ):\n        return "roll_peak"\n\n    if matches(\n        text,\n        r"\\b(?:"\n        r"recorded side|"\n        r"pdof|"\n        r"principal direction"\n        r")\\b",\n    ):\n        return "direction_summary"\n\n    # --------------------------------------------------------\n    # Trigger timing\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\btime from time zero to trg\\b",\n    ):\n        return "trigger_relative_timing"\n\n    return (\n        norm(old_family)\n        or "other_crash_measurement"\n    )\n\n\n# ============================================================\n# Review recovery\n# ============================================================\n\ndef classify_review_label(label):\n    """\n    Return:\n        decision, family, status, reason\n\n    Decisions:\n        accept\n        companion\n        exclude\n        review\n    """\n\n    text = norm(label)\n\n    # --------------------------------------------------------\n    # Recover definite Group 5 scalar measurements\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"^roll angle at the time of trg\\b",\n    ):\n        return (\n            "accept",\n            "roll_at_trigger",\n            "recovered_group5_measurement",\n            "scalar_roll_angle_at_trigger",\n        )\n\n    if matches(\n        text,\n        r"\\broll angle time zero offset\\b",\n    ):\n        return (\n            "accept",\n            "roll_time_zero_offset",\n            "recovered_group5_measurement",\n            "scalar_roll_time_alignment_measurement",\n        )\n\n    if matches(\n        text,\n        r"\\bsensor design range exceeded time\\b.*\\bacceleration\\b",\n    ):\n        return (\n            "accept",\n            "range_clipping_timing",\n            "recovered_group5_measurement",\n            "sensor_range_exceeded_timing",\n        )\n\n    if matches(\n        text,\n        r"\\bintegration time\\b.*\\bdelta[- ]?v\\b",\n    ):\n        return (\n            "accept",\n            "delta_v_integration_time",\n            "recovered_group5_measurement",\n            "scalar_delta_v_integration_time",\n        )\n\n    if matches(\n        text,\n        r"\\btime yaw rate lost\\b",\n    ):\n        return (\n            "accept",\n            "sensor_loss_timing",\n            "recovered_group5_measurement",\n            "scalar_yaw_rate_loss_timing",\n        )\n\n    if matches(\n        text,\n        r"\\btime from last speed data sample\\b.*\\btime zero\\b",\n    ):\n        return (\n            "accept",\n            "precrash_time_alignment",\n            "recovered_group5_measurement",\n            "precrash_sample_to_event_time_alignment",\n        )\n\n    # --------------------------------------------------------\n    # Group 5 companion/context fields\n    # --------------------------------------------------------\n\n    if matches(\n        text,\n        r"\\bpower supply status\\b.*\\bmax\\.?\\s*delta[- ]?v\\b",\n    ):\n        return (\n            "companion",\n            "measurement_context",\n            "group5_companion_context",\n            "status_at_delta_v_summary",\n        )\n\n    if matches(\n        text,\n        r"\\bclipping flag\\b",\n    ):\n        return (\n            "companion",\n            "measurement_quality_context",\n            "group5_companion_context",\n            "clipping_flag_context",\n        )\n\n    if matches(\n        text,\n        r"\\btime from pre[- ]?crash to trg\\b",\n    ):\n        return (\n            "companion",\n            "temporal_alignment_context",\n            "group5_companion_context",\n            "precrash_to_trigger_alignment_context",\n        )\n\n    if matches(\n        text,\n        r"\\btime from trg to next sample\\b",\n    ):\n        return (\n            "companion",\n            "temporal_alignment_context",\n            "group5_companion_context",\n            "trigger_to_next_sample_alignment_context",\n        )\n\n    # --------------------------------------------------------\n    # Explicit non-Group-5 routing\n    # --------------------------------------------------------\n\n    # Group 2: event/record structure\n    if matches(\n        text,\n        r"\\b(?:"\n        r"event\\(s\\) recovered|"\n        r"recording status|"\n        r"complete file recorded|"\n        r"previous crash type|"\n        r"event record type|"\n        r"event type|"\n        r"multi[- ]?event|"\n        r"concurrent event|"\n        r"time from event \\d+ to \\d+|"\n        r"time from previous event|"\n        r"time from initial event|"\n        r"time from previous trg|"\n        r"trg count|"\n        r"trip count"\n        r")\\b",\n    ):\n        return (\n            "exclude",\n            "group2_or_record_structure",\n            "excluded_non_group5",\n            "record_or_event_structure",\n        )\n\n    # Group 3: restraint/deployment/status\n    if matches(\n        text,\n        r"\\b(?:"\n        r"safety belt|"\n        r"seat track|"\n        r"passenger seat occupancy|"\n        r"deployment|"\n        r"event severity status|"\n        r"algorithm active|"\n        r"rsca disable|"\n        r"onstar .* data sent|"\n        r"onstar deployment|"\n        r"knee deployment|"\n        r"warning lamp|"\n        r"occupant|"\n        r"restraint"\n        r")\\b",\n    ):\n        return (\n            "exclude",\n            "group3_status",\n            "excluded_non_group5",\n            "deployment_restraint_or_event_status",\n        )\n\n    # Group 6 / technical context\n    if matches(\n        text,\n        r"\\b(?:"\n        r"odometer|"\n        r"vehicle mileage|"\n        r"operating time|"\n        r"freeze signal|"\n        r"location of .*sensor|"\n        r"supply voltage|"\n        r"vehicle clock|"\n        r"event establishment factor|"\n        r"trg establishment factor|"\n        r"time count input system|"\n        r"time count"\n        r")\\b",\n    ):\n        return (\n            "exclude",\n            "group6_technical",\n            "excluded_non_group5",\n            "technical_or_investigation_context",\n        )\n\n    # Timing of algorithm start/reset is status/control context,\n    # not a physical summary measurement for this group.\n    if matches(\n        text,\n        r"\\btime from time zero to algorithm (?:start|reset)\\b",\n    ):\n        return (\n            "exclude",\n            "group3_algorithm_status",\n            "excluded_non_group5",\n            "algorithm_state_timing",\n        )\n\n    # Rollover deployment angle belongs with deployment status,\n    # not generic crash scalar measurements.\n    if matches(\n        text,\n        r"\\broll angle\\b.*\\bdeployment\\b",\n    ):\n        return (\n            "exclude",\n            "group3_deployment_status",\n            "excluded_non_group5",\n            "deployment_related_roll_angle",\n        )\n\n    return (\n        "review",\n        "unresolved_review",\n        "remaining_review",\n        "no_safe_group5_resolution_rule",\n    )\n\n\n# ============================================================\n# Audit record\n# ============================================================\n\ndef audit_candidate(row):\n    family = refine_candidate_family(\n        row.get(\n            "field_label_raw",\n            "",\n        ),\n        row.get(\n            "candidate_family",\n            "",\n        ),\n    )\n\n    return {\n        **row,\n\n        "audited_family":\n            family,\n\n        "audit_decision":\n            "accept",\n\n        "audit_status":\n            "accepted_group5_candidate",\n\n        "audit_reason":\n            "strong_scalar_crash_measurement_pattern",\n\n        "audit_origin":\n            "discovery_candidate",\n    }\n\n\ndef audit_review(row):\n    (\n        decision,\n        family,\n        status,\n        reason,\n    ) = classify_review_label(\n        row.get(\n            "field_label_raw",\n            "",\n        )\n    )\n\n    return {\n        **row,\n\n        "audited_family":\n            family,\n\n        "audit_decision":\n            decision,\n\n        "audit_status":\n            status,\n\n        "audit_reason":\n            reason,\n\n        "audit_origin":\n            "discovery_review",\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--discovery-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_audit_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    candidate_path = (\n        args.discovery_directory\n        / "group5_candidate_fields.csv"\n    )\n\n    review_path = (\n        args.discovery_directory\n        / "group5_review_fields.csv"\n    )\n\n    if not candidate_path.exists():\n        raise FileNotFoundError(\n            candidate_path\n        )\n\n    if not review_path.exists():\n        raise FileNotFoundError(\n            review_path\n        )\n\n    candidates = read_csv(\n        candidate_path\n    )\n\n    reviews = read_csv(\n        review_path\n    )\n\n    audited = []\n\n    for row in candidates:\n        audited.append(\n            audit_candidate(row)\n        )\n\n    for row in reviews:\n        audited.append(\n            audit_review(row)\n        )\n\n    accepted = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ] == "accept"\n    ]\n\n    companions = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ] == "companion"\n    ]\n\n    excluded = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ] == "exclude"\n    ]\n\n    remaining_review = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ] == "review"\n    ]\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    family_counts = Counter(\n        row[\n            "audited_family"\n        ]\n        for row in accepted\n    )\n\n    decision_counts = Counter(\n        row[\n            "audit_decision"\n        ]\n        for row in audited\n    )\n\n    origin_decisions = Counter(\n        (\n            row[\n                "audit_origin"\n            ],\n            row[\n                "audit_decision"\n            ],\n        )\n        for row in audited\n    )\n\n    reports_with_accepted = {\n        row.get(\n            "report_id",\n            ""\n        )\n        for row in accepted\n        if row.get(\n            "report_id",\n            ""\n        )\n    }\n\n    promoted_from_review = [\n        row\n        for row in accepted\n        if row[\n            "audit_origin"\n        ] == "discovery_review"\n    ]\n\n    # Family summary\n    family_summary = [\n        {\n            "audited_family":\n                family,\n\n            "field_count":\n                count,\n\n            "report_count":\n                len(\n                    {\n                        row.get(\n                            "report_id",\n                            ""\n                        )\n                        for row in accepted\n                        if row[\n                            "audited_family"\n                        ] == family\n                        and row.get(\n                            "report_id",\n                            ""\n                        )\n                    }\n                ),\n\n            "promoted_from_review_count":\n                sum(\n                    1\n                    for row in accepted\n                    if (\n                        row[\n                            "audited_family"\n                        ] == family\n                        and row[\n                            "audit_origin"\n                        ] == "discovery_review"\n                    )\n                ),\n        }\n        for family, count\n        in family_counts.most_common()\n    ]\n\n    decision_summary = [\n        {\n            "audit_origin":\n                origin,\n\n            "audit_decision":\n                decision,\n\n            "field_count":\n                count,\n        }\n        for (\n            origin,\n            decision,\n        ), count\n        in sorted(\n            origin_decisions.items()\n        )\n    ]\n\n    # Label-decision summary\n    label_grouped = defaultdict(\n        Counter\n    )\n\n    for row in audited:\n        label = norm(\n            row.get(\n                "field_label_raw",\n                ""\n            )\n        )\n\n        label_grouped[\n            label\n        ][\n            row[\n                "audit_decision"\n            ]\n        ] += 1\n\n    label_decision_summary = []\n\n    for label, counts in sorted(\n        label_grouped.items(),\n        key=lambda item: (\n            -sum(\n                item[1].values()\n            ),\n            item[0].casefold(),\n        ),\n    ):\n        label_decision_summary.append({\n            "field_label_raw":\n                label,\n\n            "total_count":\n                sum(\n                    counts.values()\n                ),\n\n            "accept_count":\n                counts.get(\n                    "accept",\n                    0,\n                ),\n\n            "companion_count":\n                counts.get(\n                    "companion",\n                    0,\n                ),\n\n            "exclude_count":\n                counts.get(\n                    "exclude",\n                    0,\n                ),\n\n            "review_count":\n                counts.get(\n                    "review",\n                    0,\n                ),\n        })\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    input_total = (\n        len(candidates)\n        + len(reviews)\n    )\n\n    output_total = (\n        len(accepted)\n        + len(companions)\n        + len(excluded)\n        + len(remaining_review)\n    )\n\n    duplicate_ids = sum(\n        1\n        for count\n        in Counter(\n            row.get(\n                "group5_candidate_id",\n                ""\n            )\n            for row in audited\n            if row.get(\n                "group5_candidate_id",\n                ""\n            )\n        ).values()\n        if count > 1\n    )\n\n    if input_total != output_total:\n        raise RuntimeError(\n            "Audit accounting mismatch: "\n            f"{input_total} != {output_total}"\n        )\n\n    # ========================================================\n    # Write\n    # ========================================================\n\n    out = args.output_directory\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    columns = union_columns(\n        audited\n    )\n\n    write_csv(\n        out\n        / "audit_all_fields.csv",\n        audited,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "accepted_group5_fields.csv",\n        accepted,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "companion_group5_context.csv",\n        companions,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "excluded_non_group5_fields.csv",\n        excluded,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "remaining_review_fields.csv",\n        remaining_review,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "family_summary.csv",\n        family_summary,\n        [\n            "audited_family",\n            "field_count",\n            "report_count",\n            "promoted_from_review_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "decision_summary.csv",\n        decision_summary,\n        [\n            "audit_origin",\n            "audit_decision",\n            "field_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "label_decision_summary.csv",\n        label_decision_summary,\n        [\n            "field_label_raw",\n            "total_count",\n            "accept_count",\n            "companion_count",\n            "exclude_count",\n            "review_count",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "CSV candidate audit",\n\n        "input_discovery_candidates":\n            len(\n                candidates\n            ),\n\n        "input_discovery_review_fields":\n            len(\n                reviews\n            ),\n\n        "total_fields_audited":\n            len(\n                audited\n            ),\n\n        "accepted_group5_fields":\n            len(\n                accepted\n            ),\n\n        "companion_group5_context_fields":\n            len(\n                companions\n            ),\n\n        "excluded_non_group5_fields":\n            len(\n                excluded\n            ),\n\n        "remaining_review_fields":\n            len(\n                remaining_review\n            ),\n\n        "reports_with_accepted_group5_fields":\n            len(\n                reports_with_accepted\n            ),\n\n        "promoted_from_discovery_review":\n            len(\n                promoted_from_review\n            ),\n\n        "accepted_family_counts":\n            dict(\n                family_counts\n            ),\n\n        "decision_counts":\n            dict(\n                decision_counts\n            ),\n\n        "duplicate_candidate_ids":\n            duplicate_ids,\n\n        "input_accounting_total":\n            input_total,\n\n        "output_accounting_total":\n            output_total,\n\n        "all_fields_accounted_for":\n            (\n                input_total\n                == output_total\n            ),\n\n        "scope":\n            (\n                "Audit of Group 5 CSV discovery candidates and review "\n                "fields. Delta-V scalar summaries are separated from "\n                "time-of-maximum fields; peak acceleration values are "\n                "separated from peak timing; clipping/range-exceeded "\n                "timing remains a Group 5 measurement-quality family. "\n                "Selected scalar measurements are recovered from the "\n                "review population, while direct measurement context is "\n                "preserved separately as Group 5 companion metadata. "\n                "Unrelated record structure, restraint/deployment/status, "\n                "and technical/investigation fields are excluded. "\n                "No semantic value normalization, unit conversion, fuzzy "\n                "event linking, PDF processing, or final extraction is "\n                "performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 5 CSV CANDIDATE AUDIT COMPLETE."\n    )\n\n\n'

_CSV_RESOLVE_SOURCE = '"""\nResolve the remaining Group 5 CSV audit review fields and correct one\ntargeted family-classification issue.\n\nInputs\n------\ndata/processed/edr/group5_csv_audit_v1/\n    accepted_group5_fields.csv\n    companion_group5_context.csv\n    excluded_non_group5_fields.csv\n    remaining_review_fields.csv\n\nOutputs\n-------\ndata/processed/edr/group5_csv_resolved_v1/\n\n    accepted_group5_fields.csv\n    companion_group5_context.csv\n    excluded_non_group5_fields.csv\n    remaining_review_fields.csv\n    resolution_all_fields.csv\n    family_summary.csv\n    resolution_summary.csv\n    metadata.json\n\nTargeted corrections\n--------------------\n1. Reclassify scalar component values such as:\n       Longitudinal ... Velocity Change at time of Maximum ...\n       Lateral ... Velocity Change at time of Maximum ...\n   from delta_v_timing to delta_v_component_at_maximum.\n\n2. Resolve the 575 remaining review fields conservatively:\n   - Saved on -> Group 1/report metadata\n   - High Voltage Disable Notification Sent -> Group 3/status\n   - Power loss detected during Event -> Group 3/event condition\n   - Supplier ID, ACM -> Group 6/technical\n   - Production Date, ACM -> Group 6/technical\n   - Most Recent Event / Nth Prior Event -> Group 2/event structure\n\nNo accepted Group 5 value is changed, normalized, converted, or event-linked.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\ndef union_columns(*row_sets):\n    seen = set()\n    columns = []\n\n    preferred = [\n        "report_id",\n        "case_id",\n        "vehicle_number",\n        "export_basename",\n        "group5_candidate_id",\n        "field_label_raw",\n        "field_value_raw",\n        "audited_family",\n        "audit_decision",\n        "audit_status",\n        "audit_reason",\n        "resolution_decision",\n        "resolution_status",\n        "resolution_reason",\n    ]\n\n    for column in preferred:\n        if column not in seen:\n            seen.add(column)\n            columns.append(column)\n\n    for rows in row_sets:\n        for row in rows:\n            for key in row.keys():\n                if key not in seen:\n                    seen.add(key)\n                    columns.append(key)\n\n    return columns\n\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef reclassify_accepted(row):\n    label = norm(\n        row.get(\n            "field_label_raw",\n            ""\n        )\n    )\n\n    family = norm(\n        row.get(\n            "audited_family",\n            ""\n        )\n    )\n\n    if (\n        family == "delta_v_timing"\n        and re.search(\n            r"\\b(?:longitudinal|lateral)\\b",\n            label,\n            re.I,\n        )\n        and re.search(\n            r"\\bvelocity change\\b",\n            label,\n            re.I,\n        )\n        and re.search(\n            r"\\bat time of maximum\\b",\n            label,\n            re.I,\n        )\n        and not re.search(\n            r"^\\s*time\\b",\n            label,\n            re.I,\n        )\n    ):\n        row = dict(row)\n        row["audited_family"] = (\n            "delta_v_component_at_maximum"\n        )\n        row["audit_reason"] = (\n            "scalar_component_value_at_resultant_maximum"\n        )\n        row["family_resolution_note"] = (\n            "reclassified_from_delta_v_timing"\n        )\n        return row, True\n\n    row = dict(row)\n    row["family_resolution_note"] = ""\n    return row, False\n\n\ndef resolve_review(row):\n    label = norm(\n        row.get(\n            "field_label_raw",\n            ""\n        )\n    )\n\n    lower = label.casefold()\n\n    if lower == "saved on":\n        destination = "group1_report_metadata"\n        reason = "report_saved_timestamp"\n\n    elif lower == (\n        "high voltage disable notification sent"\n    ):\n        destination = "group3_event_condition_status"\n        reason = "event_related_high_voltage_status"\n\n    elif lower == (\n        "power loss detected during event"\n    ):\n        destination = "group3_event_condition_status"\n        reason = "power_loss_event_condition"\n\n    elif lower == "supplier id, acm":\n        destination = "group6_technical"\n        reason = "module_supplier_identifier"\n\n    elif lower == "production date, acm":\n        destination = "group6_technical"\n        reason = "module_production_metadata"\n\n    elif re.fullmatch(\n        r"(?:"\n        r"most recent event|"\n        r"\\d+(?:st|nd|rd|th) prior event"\n        r")",\n        lower,\n        re.I,\n    ):\n        destination = "group2_event_structure"\n        reason = "event_record_label"\n\n    else:\n        return {\n            **row,\n            "resolution_decision":\n                "review",\n            "resolution_status":\n                "remaining_review",\n            "resolution_reason":\n                "no_safe_resolution_rule",\n            "resolution_destination":\n                "",\n        }\n\n    return {\n        **row,\n        "resolution_decision":\n            "exclude",\n        "resolution_status":\n            "resolved_non_group5",\n        "resolution_reason":\n            reason,\n        "resolution_destination":\n            destination,\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--audit-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_audit_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_resolved_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    required = {\n        "accepted":\n            args.audit_directory\n            / "accepted_group5_fields.csv",\n\n        "companions":\n            args.audit_directory\n            / "companion_group5_context.csv",\n\n        "excluded":\n            args.audit_directory\n            / "excluded_non_group5_fields.csv",\n\n        "review":\n            args.audit_directory\n            / "remaining_review_fields.csv",\n    }\n\n    for name, path in required.items():\n        if not path.exists():\n            raise FileNotFoundError(\n                f"Missing {name}: {path}"\n            )\n\n    accepted_input = read_csv(\n        required["accepted"]\n    )\n\n    companions = read_csv(\n        required["companions"]\n    )\n\n    excluded_existing = read_csv(\n        required["excluded"]\n    )\n\n    review_input = read_csv(\n        required["review"]\n    )\n\n    accepted = []\n    reclassified_count = 0\n\n    for row in accepted_input:\n        resolved, changed = (\n            reclassify_accepted(row)\n        )\n        accepted.append(resolved)\n\n        if changed:\n            reclassified_count += 1\n\n    resolved_review = [\n        resolve_review(row)\n        for row in review_input\n    ]\n\n    resolved_non_group5 = [\n        row\n        for row in resolved_review\n        if row[\n            "resolution_decision"\n        ] == "exclude"\n    ]\n\n    remaining_review = [\n        row\n        for row in resolved_review\n        if row[\n            "resolution_decision"\n        ] == "review"\n    ]\n\n    final_excluded = (\n        list(excluded_existing)\n        + resolved_non_group5\n    )\n\n    input_total = (\n        len(accepted_input)\n        + len(companions)\n        + len(excluded_existing)\n        + len(review_input)\n    )\n\n    output_total = (\n        len(accepted)\n        + len(companions)\n        + len(final_excluded)\n        + len(remaining_review)\n    )\n\n    if input_total != output_total:\n        raise RuntimeError(\n            "Resolution accounting mismatch: "\n            f"{input_total} != {output_total}"\n        )\n\n    family_counts = Counter(\n        row.get(\n            "audited_family",\n            ""\n        )\n        for row in accepted\n    )\n\n    resolution_counts = Counter(\n        row[\n            "resolution_destination"\n        ]\n        for row in resolved_non_group5\n    )\n\n    out = args.output_directory\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    all_columns = union_columns(\n        accepted,\n        companions,\n        final_excluded,\n        remaining_review,\n    )\n\n    write_csv(\n        out\n        / "accepted_group5_fields.csv",\n        accepted,\n        all_columns,\n    )\n\n    write_csv(\n        out\n        / "companion_group5_context.csv",\n        companions,\n        all_columns,\n    )\n\n    write_csv(\n        out\n        / "excluded_non_group5_fields.csv",\n        final_excluded,\n        all_columns,\n    )\n\n    write_csv(\n        out\n        / "remaining_review_fields.csv",\n        remaining_review,\n        all_columns,\n    )\n\n    write_csv(\n        out\n        / "resolution_all_fields.csv",\n        resolved_review,\n        all_columns,\n    )\n\n    family_summary = [\n        {\n            "audited_family":\n                family,\n            "field_count":\n                count,\n        }\n        for family, count\n        in family_counts.most_common()\n    ]\n\n    write_csv(\n        out\n        / "family_summary.csv",\n        family_summary,\n        [\n            "audited_family",\n            "field_count",\n        ],\n    )\n\n    resolution_summary = [\n        {\n            "resolution_destination":\n                destination,\n            "field_count":\n                count,\n        }\n        for destination, count\n        in resolution_counts.most_common()\n    ]\n\n    write_csv(\n        out\n        / "resolution_summary.csv",\n        resolution_summary,\n        [\n            "resolution_destination",\n            "field_count",\n        ],\n    )\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "CSV residual review resolution",\n\n        "input_accepted_group5_fields":\n            len(accepted_input),\n\n        "reclassified_accepted_fields":\n            reclassified_count,\n\n        "input_remaining_review_fields":\n            len(review_input),\n\n        "resolved_non_group5_fields":\n            len(resolved_non_group5),\n\n        "remaining_review_fields":\n            len(remaining_review),\n\n        "final_accepted_group5_fields":\n            len(accepted),\n\n        "final_companion_group5_context_fields":\n            len(companions),\n\n        "final_excluded_non_group5_fields":\n            len(final_excluded),\n\n        "accepted_family_counts":\n            dict(family_counts),\n\n        "resolution_destination_counts":\n            dict(resolution_counts),\n\n        "input_accounting_total":\n            input_total,\n\n        "output_accounting_total":\n            output_total,\n\n        "all_fields_accounted_for":\n            (\n                input_total\n                == output_total\n            ),\n\n        "scope":\n            (\n                "Targeted resolution of the Group 5 CSV audit residual "\n                "population plus one family-classification correction. "\n                "Component velocity-change values reported at the time "\n                "of maximum resultant velocity change are reclassified "\n                "as scalar component measurements rather than timing "\n                "fields. The residual review population is routed to "\n                "Group 1, Group 2, Group 3, or Group 6 based only on "\n                "explicit labels. No Group 5 values are normalized or "\n                "converted, and no fuzzy event identity inference is "\n                "performed."\n            ),\n    }\n\n    tmp = out / "metadata.json.part"\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 5 CSV REVIEW RESOLUTION COMPLETE."\n    )\n\n\n'

_CSV_EXTRACT_SOURCE = '"""\nBuild structured Group 5 CSV scalar crash/event measurement datasets.\n\nInput\n-----\ndata/processed/edr/group5_csv_resolved_v1/\n    accepted_group5_fields.csv\n    companion_group5_context.csv\n\nOutput\n------\ndata/processed/edr/group5_csv_structured_v1/\n\n    measurement_registry.csv\n    measurement_values.csv\n    companion_context.csv\n    extraction_audit.csv\n    extraction_failures.csv\n    validation_report.csv\n    metadata.json\n\nPurpose\n-------\nConvert the resolved Group 5 CSV field population into a structured scalar\nmeasurement package while preserving the original labels, values, units,\nsource rows, report/case/vehicle linkage, section context, and event hints.\n\nImportant rules\n---------------\n- One accepted source field becomes one measurement record.\n- Raw labels and raw values are preserved exactly as extracted.\n- Parsed numeric values are added only when safely recoverable.\n- Raw units are inferred conservatively from the label/value.\n- No semantic normalization is performed.\n- No unit conversion is performed.\n- No fuzzy event identity inference is performed.\n- Event hints remain source hints only.\n- Companion/context fields remain separate from primary measurements.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nimport re\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# Helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode("utf-8")\n    ).hexdigest()[:24]\n\n\nMISSING_VALUES = {\n    "",\n    "n/a",\n    "na",\n    "sna",\n    "not available",\n    "data not available",\n    "not applicable",\n    "unknown",\n    "invalid",\n    "not recorded",\n}\n\n\ndef is_missing_or_na(value):\n    return norm(value).casefold() in MISSING_VALUES\n\n\n# ============================================================\n# Unit parsing\n# ============================================================\n\nUNIT_PATTERNS = [\n    ("mph", r"\\bmph\\b"),\n    ("km/h", r"\\bkm/h\\b|\\bkph\\b"),\n    ("m/s", r"\\bm/s\\b"),\n    ("g", r"(?<![a-z])g(?![a-z])"),\n    ("m/s^2", r"\\bm/s(?:\\^?2|²)\\b"),\n    ("ft/s^2", r"\\bft/s(?:\\^?2|²)\\b"),\n    ("ms", r"\\bmsec\\b|\\bmilliseconds?\\b|\\bms\\b"),\n    ("s", r"\\bseconds?\\b|\\bsec\\b"),\n    ("deg", r"\\bdegrees?\\b|\\bdeg\\b"),\n    ("deg/s", r"\\bdeg/s\\b|\\bdegrees?/sec\\b"),\n    ("rad/s", r"\\brad/s\\b"),\n    ("%", r"%|\\bpercent\\b"),\n]\n\n\ndef extract_unit(label, value):\n    """\n    Conservative raw-unit extraction.\n\n    Prefer units embedded in the field label. If absent, inspect the raw value.\n    """\n\n    label_text = norm(label)\n    value_text = norm(value)\n\n    # Parenthesized units in labels are strongest evidence.\n    for content in reversed(\n        re.findall(\n            r"\\(([^()]*)\\)",\n            label_text,\n        )\n    ):\n        candidate = norm(content)\n\n        for canonical, pattern in UNIT_PATTERNS:\n            if re.search(\n                pattern,\n                candidate,\n                re.I,\n            ):\n                return candidate\n\n    # Otherwise search label for known unit tokens.\n    for canonical, pattern in UNIT_PATTERNS:\n        match = re.search(\n            pattern,\n            label_text,\n            re.I,\n        )\n\n        if match:\n            return norm(\n                match.group(0)\n            )\n\n    # Finally inspect the raw value suffix.\n    for canonical, pattern in UNIT_PATTERNS:\n        match = re.search(\n            pattern,\n            value_text,\n            re.I,\n        )\n\n        if match:\n            return norm(\n                match.group(0)\n            )\n\n    return ""\n\n\n# ============================================================\n# Numeric parsing\n# ============================================================\n\nNUMERIC_PATTERN = re.compile(\n    r"[-+]?"\n    r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n    r"(?:[eE][-+]?\\d+)?"\n)\n\n\ndef parse_numeric(value):\n    """\n    Parse only if the source value is safely interpretable as one scalar number.\n\n    Examples accepted:\n        -20.26\n        117.5\n        -5.35 MPH\n        150 msec\n\n    Examples not forced:\n        Left\n        Yes\n        10-20\n        3/4\n    """\n\n    text = norm(value)\n\n    if not text:\n        return ""\n\n    if is_missing_or_na(text):\n        return ""\n\n    cleaned = text.replace(\n        ",",\n        "",\n    )\n\n    # Remove common unit suffixes.\n    cleaned = re.sub(\n        r"\\s*(?:"\n        r"mph|km/h|kph|m/s|m/s\\^?2|m/s²|"\n        r"ft/s\\^?2|ft/s²|"\n        r"g|ms|msec|milliseconds?|"\n        r"sec|seconds?|"\n        r"deg|degrees?|deg/s|rad/s|"\n        r"%|percent"\n        r")\\s*$",\n        "",\n        cleaned,\n        flags=re.I,\n    )\n\n    cleaned = norm(cleaned)\n\n    if not re.fullmatch(\n        NUMERIC_PATTERN,\n        cleaned,\n    ):\n        return ""\n\n    try:\n        number = float(cleaned)\n\n        if math.isfinite(number):\n            return number\n\n    except ValueError:\n        pass\n\n    return ""\n\n\n# ============================================================\n# Measurement records\n# ============================================================\n\ndef build_measurement(source):\n    candidate_id = norm(\n        source.get(\n            "group5_candidate_id",\n            ""\n        )\n    )\n\n    if not candidate_id:\n        raise ValueError(\n            "Missing group5_candidate_id."\n        )\n\n    label = norm(\n        source.get(\n            "field_label_raw",\n            ""\n        )\n    )\n\n    if not label:\n        raise ValueError(\n            "Missing field_label_raw."\n        )\n\n    raw_value = norm(\n        source.get(\n            "field_value_raw",\n            ""\n        )\n    )\n\n    measurement_id = (\n        "g5csvmeas_"\n        + identifier(\n            source.get(\n                "report_id",\n                ""\n            ),\n            candidate_id,\n            source.get(\n                "source_record_index",\n                ""\n            ),\n            label,\n        )\n    )\n\n    unit = extract_unit(\n        label,\n        raw_value,\n    )\n\n    numeric = parse_numeric(\n        raw_value\n    )\n\n    return {\n        **{\n            key:\n                source.get(\n                    key,\n                    ""\n                )\n            for key in BASE\n        },\n\n        "measurement_id":\n            measurement_id,\n\n        "group5_candidate_id":\n            candidate_id,\n\n        "source_format":\n            "csv",\n\n        "source_path":\n            source.get(\n                "source_path",\n                "",\n            ),\n\n        "source_record_index":\n            source.get(\n                "source_record_index",\n                "",\n            ),\n\n        "source_section_heading":\n            source.get(\n                "source_section_heading",\n                "",\n            ),\n\n        "event_hint":\n            source.get(\n                "event_hint",\n                "",\n            ),\n\n        "event_link_status":\n            source.get(\n                "event_link_status",\n                "",\n            )\n            or "not_linked",\n\n        "family":\n            source.get(\n                "audited_family",\n                "",\n            ),\n\n        "field_label_raw":\n            label,\n\n        "field_value_raw":\n            raw_value,\n\n        "field_value_numeric":\n            numeric,\n\n        "field_value_is_missing_or_na":\n            is_missing_or_na(\n                raw_value\n            ),\n\n        "unit_raw":\n            unit,\n\n        "source_row_json":\n            source.get(\n                "source_row_json",\n                "",\n            ),\n\n        "source_value_column_index":\n            source.get(\n                "value_column_index",\n                "",\n            ),\n\n        "group4_companion_support_count":\n            source.get(\n                "group4_companion_support_count",\n                "",\n            ),\n\n        "processing_status":\n            "structured_extracted",\n\n        "semantic_normalization_status":\n            "not_normalized",\n\n        "unit_conversion_status":\n            "not_converted",\n    }\n\n\ndef build_companion(source):\n    candidate_id = norm(\n        source.get(\n            "group5_candidate_id",\n            ""\n        )\n    )\n\n    companion_id = (\n        "g5csvctx_"\n        + identifier(\n            source.get(\n                "report_id",\n                ""\n            ),\n            candidate_id,\n            source.get(\n                "source_record_index",\n                ""\n            ),\n            source.get(\n                "field_label_raw",\n                ""\n            ),\n        )\n    )\n\n    return {\n        **{\n            key:\n                source.get(\n                    key,\n                    ""\n                )\n            for key in BASE\n        },\n\n        "companion_context_id":\n            companion_id,\n\n        "group5_candidate_id":\n            candidate_id,\n\n        "source_format":\n            "csv",\n\n        "source_path":\n            source.get(\n                "source_path",\n                "",\n            ),\n\n        "source_record_index":\n            source.get(\n                "source_record_index",\n                "",\n            ),\n\n        "source_section_heading":\n            source.get(\n                "source_section_heading",\n                "",\n            ),\n\n        "event_hint":\n            source.get(\n                "event_hint",\n                "",\n            ),\n\n        "field_label_raw":\n            source.get(\n                "field_label_raw",\n                "",\n            ),\n\n        "field_value_raw":\n            source.get(\n                "field_value_raw",\n                "",\n            ),\n\n        "audited_family":\n            source.get(\n                "audited_family",\n                "",\n            ),\n\n        "audit_reason":\n            source.get(\n                "audit_reason",\n                "",\n            ),\n\n        "source_row_json":\n            source.get(\n                "source_row_json",\n                "",\n            ),\n\n        "processing_status":\n            "preserved_group5_companion_context",\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--resolved-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_resolved_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_structured_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    accepted_path = (\n        args.resolved_directory\n        / "accepted_group5_fields.csv"\n    )\n\n    companion_path = (\n        args.resolved_directory\n        / "companion_group5_context.csv"\n    )\n\n    if not accepted_path.exists():\n        raise FileNotFoundError(\n            accepted_path\n        )\n\n    if not companion_path.exists():\n        raise FileNotFoundError(\n            companion_path\n        )\n\n    accepted = read_csv(\n        accepted_path\n    )\n\n    companion_input = read_csv(\n        companion_path\n    )\n\n    measurements = []\n    companion_rows = []\n    audit_rows = []\n    failures = []\n\n    # ========================================================\n    # Primary measurement extraction\n    # ========================================================\n\n    for index, source in enumerate(\n        accepted,\n        1,\n    ):\n        try:\n            record = build_measurement(\n                source\n            )\n\n            measurements.append(\n                record\n            )\n\n            audit_rows.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "group5_candidate_id":\n                    source.get(\n                        "group5_candidate_id",\n                        "",\n                    ),\n\n                "measurement_id":\n                    record[\n                        "measurement_id"\n                    ],\n\n                "family":\n                    record[\n                        "family"\n                    ],\n\n                "field_label_raw":\n                    record[\n                        "field_label_raw"\n                    ],\n\n                "field_value_raw":\n                    record[\n                        "field_value_raw"\n                    ],\n\n                "field_value_numeric":\n                    record[\n                        "field_value_numeric"\n                    ],\n\n                "unit_raw":\n                    record[\n                        "unit_raw"\n                    ],\n\n                "status":\n                    "success",\n\n                "issue":\n                    "",\n            })\n\n        except Exception as exc:\n            failures.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "group5_candidate_id":\n                    source.get(\n                        "group5_candidate_id",\n                        "",\n                    ),\n\n                "field_label_raw":\n                    source.get(\n                        "field_label_raw",\n                        "",\n                    ),\n\n                "field_value_raw":\n                    source.get(\n                        "field_value_raw",\n                        "",\n                    ),\n\n                "error_type":\n                    type(exc).__name__,\n\n                "error":\n                    str(exc),\n            })\n\n        if (\n            index % 1000 == 0\n            or index\n            == len(accepted)\n        ):\n            print(\n                "Structured Group 5 CSV "\n                f"{index}/{len(accepted)} fields...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Companion/context extraction\n    # ========================================================\n\n    for source in companion_input:\n        companion_rows.append(\n            build_companion(\n                source\n            )\n        )\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    validation = []\n\n    def check(\n        name,\n        condition,\n        observed,\n        expected,\n        severity="hard",\n        note="",\n    ):\n        validation.append({\n            "check":\n                name,\n\n            "status":\n                (\n                    "PASS"\n                    if condition\n                    else "FAIL"\n                ),\n\n            "severity":\n                severity,\n\n            "observed":\n                str(observed),\n\n            "expected":\n                str(expected),\n\n            "note":\n                note,\n        })\n\n    check(\n        "accepted_fields_accounted_for",\n        (\n            len(measurements)\n            + len(failures)\n            == len(accepted)\n        ),\n        (\n            len(measurements)\n            + len(failures)\n        ),\n        len(accepted),\n    )\n\n    check(\n        "expected_input_accepted_count",\n        len(accepted) == 10595,\n        len(accepted),\n        10595,\n        severity="warning",\n    )\n\n    check(\n        "expected_companion_count",\n        len(companion_rows) == 1166,\n        len(companion_rows),\n        1166,\n        severity="warning",\n    )\n\n    measurement_ids = [\n        row["measurement_id"]\n        for row in measurements\n    ]\n\n    duplicate_measurement_ids = (\n        len(measurement_ids)\n        - len(\n            set(\n                measurement_ids\n            )\n        )\n    )\n\n    check(\n        "measurement_ids_unique",\n        duplicate_measurement_ids == 0,\n        duplicate_measurement_ids,\n        0,\n    )\n\n    candidate_ids = [\n        row["group5_candidate_id"]\n        for row in measurements\n    ]\n\n    duplicate_candidate_ids = (\n        len(candidate_ids)\n        - len(\n            set(\n                candidate_ids\n            )\n        )\n    )\n\n    check(\n        "candidate_ids_unique_in_measurements",\n        duplicate_candidate_ids == 0,\n        duplicate_candidate_ids,\n        0,\n    )\n\n    blank_labels = sum(\n        1\n        for row in measurements\n        if not norm(\n            row["field_label_raw"]\n        )\n    )\n\n    check(\n        "blank_field_labels",\n        blank_labels == 0,\n        blank_labels,\n        0,\n    )\n\n    blank_families = sum(\n        1\n        for row in measurements\n        if not norm(\n            row["family"]\n        )\n    )\n\n    check(\n        "blank_measurement_families",\n        blank_families == 0,\n        blank_families,\n        0,\n    )\n\n    source_format_errors = sum(\n        1\n        for row in measurements\n        if row[\n            "source_format"\n        ] != "csv"\n    )\n\n    check(\n        "source_format_is_csv",\n        source_format_errors == 0,\n        source_format_errors,\n        0,\n    )\n\n    numeric_value_count = sum(\n        1\n        for row in measurements\n        if row[\n            "field_value_numeric"\n        ] != ""\n    )\n\n    missing_value_count = sum(\n        1\n        for row in measurements\n        if row[\n            "field_value_is_missing_or_na"\n        ]\n    )\n\n    raw_unit_count = sum(\n        1\n        for row in measurements\n        if norm(\n            row["unit_raw"]\n        )\n    )\n\n    # Families should be one of the resolved audit families.\n    family_counts = Counter(\n        row["family"]\n        for row in measurements\n    )\n\n    expected_families = {\n        "delta_v_summary",\n        "delta_v_timing",\n        "acceleration_peak",\n        "acceleration_peak_timing",\n        "trigger_relative_timing",\n        "delta_v_duration",\n        "range_clipping_timing",\n        "delta_v_time_zero_offset",\n        "direction_summary",\n        "roll_peak",\n        "delta_v_component_at_maximum",\n        "roll_time_zero_offset",\n        "roll_at_trigger",\n        "precrash_time_alignment",\n        "sensor_loss_timing",\n        "delta_v_integration_time",\n    }\n\n    unexpected_families = sorted(\n        family\n        for family in family_counts\n        if family\n        not in expected_families\n    )\n\n    check(\n        "unexpected_family_count",\n        len(\n            unexpected_families\n        )\n        == 0,\n        len(\n            unexpected_families\n        ),\n        0,\n        severity="warning",\n        note=json.dumps(\n            unexpected_families,\n            ensure_ascii=False,\n        ),\n    )\n\n    # ========================================================\n    # Write outputs\n    # ========================================================\n\n    out = args.output_directory\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    write_csv(\n        out\n        / "measurement_registry.csv",\n        measurements,\n        [\n            *BASE,\n            "measurement_id",\n            "group5_candidate_id",\n            "source_format",\n            "source_path",\n            "source_record_index",\n            "source_section_heading",\n            "event_hint",\n            "event_link_status",\n            "family",\n            "field_label_raw",\n            "field_value_raw",\n            "field_value_numeric",\n            "field_value_is_missing_or_na",\n            "unit_raw",\n            "source_row_json",\n            "source_value_column_index",\n            "group4_companion_support_count",\n            "processing_status",\n            "semantic_normalization_status",\n            "unit_conversion_status",\n        ],\n    )\n\n    # Alias with a value-centric name for downstream convenience.\n    write_csv(\n        out\n        / "measurement_values.csv",\n        measurements,\n        [\n            *BASE,\n            "measurement_id",\n            "group5_candidate_id",\n            "event_hint",\n            "event_link_status",\n            "family",\n            "field_label_raw",\n            "field_value_raw",\n            "field_value_numeric",\n            "field_value_is_missing_or_na",\n            "unit_raw",\n            "source_path",\n            "source_record_index",\n            "source_section_heading",\n            "source_row_json",\n            "processing_status",\n            "semantic_normalization_status",\n            "unit_conversion_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "companion_context.csv",\n        companion_rows,\n        [\n            *BASE,\n            "companion_context_id",\n            "group5_candidate_id",\n            "source_format",\n            "source_path",\n            "source_record_index",\n            "source_section_heading",\n            "event_hint",\n            "field_label_raw",\n            "field_value_raw",\n            "audited_family",\n            "audit_reason",\n            "source_row_json",\n            "processing_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "extraction_audit.csv",\n        audit_rows,\n        [\n            *BASE,\n            "group5_candidate_id",\n            "measurement_id",\n            "family",\n            "field_label_raw",\n            "field_value_raw",\n            "field_value_numeric",\n            "unit_raw",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "extraction_failures.csv",\n        failures,\n        [\n            *BASE,\n            "group5_candidate_id",\n            "field_label_raw",\n            "field_value_raw",\n            "error_type",\n            "error",\n        ],\n    )\n\n    write_csv(\n        out\n        / "validation_report.csv",\n        validation,\n        [\n            "check",\n            "status",\n            "severity",\n            "observed",\n            "expected",\n            "note",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    reports_with_measurements = {\n        row["report_id"]\n        for row in measurements\n        if norm(\n            row["report_id"]\n        )\n    }\n\n    cases_with_measurements = {\n        row["case_id"]\n        for row in measurements\n        if norm(\n            row["case_id"]\n        )\n    }\n\n    hard_failures = [\n        row\n        for row in validation\n        if (\n            row["status"]\n            == "FAIL"\n            and row["severity"]\n            == "hard"\n        )\n    ]\n\n    warning_failures = [\n        row\n        for row in validation\n        if (\n            row["status"]\n            == "FAIL"\n            and row["severity"]\n            == "warning"\n        )\n    ]\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "CSV structural extraction",\n\n        "input_accepted_fields":\n            len(accepted),\n\n        "structured_measurement_count":\n            len(measurements),\n\n        "companion_context_count":\n            len(companion_rows),\n\n        "extraction_failure_count":\n            len(failures),\n\n        "reports_with_structured_measurements":\n            len(\n                reports_with_measurements\n            ),\n\n        "cases_with_structured_measurements":\n            len(\n                cases_with_measurements\n            ),\n\n        "family_counts":\n            dict(\n                family_counts\n            ),\n\n        "numeric_value_count":\n            numeric_value_count,\n\n        "missing_or_unavailable_value_count":\n            missing_value_count,\n\n        "measurement_rows_with_raw_unit":\n            raw_unit_count,\n\n        "unique_raw_field_labels":\n            len(\n                {\n                    row["field_label_raw"]\n                    for row in measurements\n                }\n            ),\n\n        "validation_checks":\n            len(validation),\n\n        "validation_failures":\n            sum(\n                1\n                for row in validation\n                if row["status"]\n                == "FAIL"\n            ),\n\n        "hard_validation_failures":\n            len(\n                hard_failures\n            ),\n\n        "warning_validation_failures":\n            len(\n                warning_failures\n            ),\n\n        "scope":\n            (\n                "Structural extraction of resolved Group 5 CSV scalar "\n                "crash/event measurements. Each accepted source field is "\n                "preserved as one structured measurement with report, case, "\n                "vehicle, source row, section, event hint, raw label, raw "\n                "value, conservatively parsed numeric value, and raw unit. "\n                "Companion/context fields remain separate. No semantic "\n                "normalization, unit conversion, fuzzy event identity "\n                "inference, PDF processing, or CSV/PDF integration is "\n                "performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    if hard_failures:\n        print()\n        print(\n            "GROUP 5 CSV STRUCTURAL EXTRACTION "\n            "HAS HARD VALIDATION FAILURES."\n        )\n\n        for row in hard_failures:\n            print(\n                f"- {row[\'check\']}: "\n                f"observed={row[\'observed\']} "\n                f"expected={row[\'expected\']}"\n            )\n\n        raise SystemExit(1)\n\n    print()\n    print(\n        "GROUP 5 CSV STRUCTURAL EXTRACTION COMPLETE."\n    )\n\n\n'

_PDF_DISCOVERY_SOURCE = '"""\nDiscover Group 5 measurements in PDF-only EDR reports.\n\nInputs\n------\ndata/processed/edr/group1_v4/report_index.csv\n\nOptional Group 5 CSV vocabulary support\n---------------------------------------\ndata/processed/edr/group5_csv_final_v1/measurement_registry.csv\n\nAuthoritative source\n--------------------\nOriginal PDF reports referenced by report_index.csv.\n\nOutput\n------\ndata/processed/edr/group5_pdf_discovery_v1/\n\n    group5_pdf_candidate_fields.csv\n    group5_pdf_review_fields.csv\n    group5_pdf_excluded_overlap_fields.csv\n    group5_pdf_report_coverage.csv\n    group5_pdf_label_summary.csv\n    group5_pdf_family_summary.csv\n    group5_pdf_section_summary.csv\n    pdf_source_errors.csv\n    metadata.json\n\nScope\n-----\nProcess ONLY PDF-only reports.\n\nThis is discovery only:\n- preserve original PDF page, line, label, value, unit, section and provenance\n- no semantic value normalization\n- no unit conversion\n- no fuzzy event identity inference\n- no OCR\n- no final structured extraction\n\nThe original PDF is authoritative. The frozen Group 5 CSV package is used only\nas optional vocabulary support for label recognition.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport re\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path, PureWindowsPath\n\ntry:\n    import pdfplumber\nexcept ImportError as exc:\n    raise SystemExit(\n        "pdfplumber is required. Install it with:\\n"\n        "  uv add pdfplumber\\n"\n        "or\\n"\n        "  uv pip install pdfplumber"\n    ) from exc\n\n\ncsv.field_size_limit(100_000_000)\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv_dict(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(path: Path, rows: list[dict], columns: list[str]):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# Helpers\n# ============================================================\n\ndef clean(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value if value is not None else "").strip(),\n    )\n\n\ndef norm_key(value):\n    return clean(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            clean(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        clean(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode("utf-8")\n    ).hexdigest()[:24]\n\n\ndef is_numeric_like(value):\n    text = clean(value).replace(",", "")\n\n    if not text:\n        return False\n\n    text = re.sub(\n        r"\\s*(?:"\n        r"mph|km/h|kph|m/s|m/s\\^?2|m/s²|"\n        r"ft/s\\^?2|ft/s²|g|"\n        r"ms|msec|milliseconds?|"\n        r"sec|seconds?|"\n        r"deg|degrees?|deg/s|rad/s|"\n        r"%|percent"\n        r")\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef is_value_like(value):\n    text = clean(value)\n\n    if not text:\n        return False\n\n    if is_numeric_like(text):\n        return True\n\n    if text.casefold() in {\n        "n/a",\n        "na",\n        "sna",\n        "not available",\n        "unknown",\n        "invalid",\n        "not recorded",\n        "yes",\n        "no",\n        "left",\n        "right",\n        "front",\n        "rear",\n        "frontal",\n        "side",\n        "rollover",\n    }:\n        return True\n\n    return False\n\n\n# ============================================================\n# Path resolution\n# ============================================================\n\ndef pdf_only_report(row):\n    csv_path = clean(row.get("csv_path", ""))\n    csv_status = clean(row.get("csv_status", "")).casefold()\n\n    pdf_path = clean(row.get("pdf_path", ""))\n    pdf_status = clean(row.get("pdf_status", "")).casefold()\n\n    has_pdf = bool(pdf_path) and pdf_status not in {\n        "missing",\n        "not_available",\n        "none",\n    }\n\n    has_csv = bool(csv_path) and csv_status not in {\n        "missing",\n        "not_available",\n        "none",\n    }\n\n    return has_pdf and not has_csv\n\n\ndef resolve_pdf_path(row: dict, source_root: Path):\n    raw = clean(row.get("pdf_path", ""))\n\n    if raw:\n        direct = Path(raw)\n\n        if direct.exists():\n            return direct\n\n        basename = PureWindowsPath(raw).name\n        case_id = clean(row.get("case_id", ""))\n\n        if case_id and basename:\n            case_root = source_root / case_id\n\n            if case_root.exists():\n                matches = list(\n                    case_root.rglob(basename)\n                )\n\n                if matches:\n                    return matches[0]\n\n    basename = clean(\n        row.get(\n            "export_basename",\n            "",\n        )\n    )\n    case_id = clean(row.get("case_id", ""))\n\n    if basename and case_id:\n        case_root = source_root / case_id\n\n        if case_root.exists():\n            matches = list(\n                case_root.rglob(\n                    basename + ".PDF"\n                )\n            )\n\n            if not matches:\n                matches = list(\n                    case_root.rglob(\n                        basename + ".pdf"\n                    )\n                )\n\n            if matches:\n                return matches[0]\n\n    return None\n\n\n# ============================================================\n# PDF text extraction\n# ============================================================\n\ndef extract_pages(pdf_path: Path):\n    pages = []\n\n    with pdfplumber.open(pdf_path) as pdf:\n        for page_number, page in enumerate(\n            pdf.pages,\n            1,\n        ):\n            text = page.extract_text(\n                x_tolerance=2,\n                y_tolerance=2,\n                layout=False,\n            ) or ""\n\n            lines = [\n                clean(line)\n                for line in text.splitlines()\n                if clean(line)\n            ]\n\n            pages.append(\n                (\n                    page_number,\n                    lines,\n                )\n            )\n\n    return pages\n\n\n# ============================================================\n# Section / event context\n# ============================================================\n\nSECTION_PATTERNS = [\n    r"^System Status At\\b",\n    r"^Event Data\\b",\n    r"^Crash Data\\b",\n    r"^Deployment Data\\b",\n    r"^Non[- ]Deployment Data\\b",\n    r"^Rollover Data\\b",\n    r"^Side Impact Data\\b",\n    r"^Longitudinal Delta[- ]?V\\b",\n    r"^Lateral Delta[- ]?V\\b",\n    r"^Multiple Event Data\\b",\n    r"^Pre[- ]?Crash Data\\b",\n]\n\nEVENT_PATTERNS = [\n    r"\\bDeployment Event\\s*#?\\s*\\d*\\b",\n    r"\\bNon[- ]Deployment Event\\b",\n    r"\\bMost Recent Event\\b",\n    r"\\b\\d+(?:st|nd|rd|th) Prior Event\\b",\n    r"\\bEvent Record\\s*#?\\s*\\d+\\b",\n]\n\n\ndef detect_section(line):\n    text = clean(line)\n\n    for pattern in SECTION_PATTERNS:\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        ):\n            return text\n\n    return ""\n\n\ndef extract_event_hint(*texts):\n    combined = " | ".join(\n        clean(text)\n        for text in texts\n        if clean(text)\n    )\n\n    hints = []\n\n    for pattern in EVENT_PATTERNS:\n        for match in re.findall(\n            pattern,\n            combined,\n            flags=re.I,\n        ):\n            value = clean(match)\n\n            if value.casefold() not in {\n                item.casefold()\n                for item in hints\n            }:\n                hints.append(value)\n\n    return " | ".join(hints)\n\n\n# ============================================================\n# Group 5 family rules\n# ============================================================\n\nFAMILY_RULES = [\n    (\n        "range_clipping_timing",\n        [\n            r"\\bclipping time\\b",\n            r"\\baccelerometer range exceeded\\b",\n            r"\\bsensor design range exceeded\\b",\n            r"\\breached maximum sensor range\\b",\n        ],\n    ),\n    (\n        "acceleration_peak_timing",\n        [\n            r"\\btime\\b.*\\bmaximum acceleration\\b",\n        ],\n    ),\n    (\n        "acceleration_peak",\n        [\n            r"\\bmaximum acceleration\\b",\n            r"\\bpeak acceleration\\b",\n        ],\n    ),\n    (\n        "delta_v_timing",\n        [\n            r"\\balgorithm enable\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\btime\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\btime\\b.*\\bmaximum\\b.*\\bdelta[- ]?v\\b",\n            r"\\btime to\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\btime from\\b.*\\bmaximum\\b.*\\bvelocity change\\b",\n        ],\n    ),\n    (\n        "delta_v_time_zero_offset",\n        [\n            r"\\bdelta[- ]?v\\b.*\\btime zero offset\\b",\n        ],\n    ),\n    (\n        "delta_v_duration",\n        [\n            r"\\blength of delta[- ]?v\\b",\n            r"\\bduration\\b.*\\bdelta[- ]?v\\b",\n            r"\\bcrash pulse\\b.*\\bduration\\b",\n        ],\n    ),\n    (\n        "delta_v_integration_time",\n        [\n            r"\\bintegration time\\b.*\\bdelta[- ]?v\\b",\n        ],\n    ),\n    (\n        "delta_v_component_at_maximum",\n        [\n            r"\\b(?:longitudinal|lateral)\\b.*"\n            r"\\bvelocity change\\b.*"\n            r"\\bat time of maximum\\b",\n        ],\n    ),\n    (\n        "delta_v_summary",\n        [\n            r"\\bmaximum\\b.*\\bvelocity change\\b",\n            r"\\bmaximum\\b.*\\bdelta[- ]?v\\b",\n            r"\\bmax(?:imum)?\\b.*\\bvelocity change\\b",\n            r"\\bmax(?:imum)?\\b.*\\bdelta[- ]?v\\b",\n            r"\\bresultant\\b.*\\bdelta[- ]?v\\b",\n            r"\\bfinal\\b.*\\bdelta[- ]?v\\b",\n            r"\\bfinal\\b.*\\bvelocity change\\b",\n        ],\n    ),\n    (\n        "roll_peak",\n        [\n            r"\\broll ?angle peak\\b",\n            r"\\bmaximum\\b.*\\broll angle\\b",\n            r"\\bpeak\\b.*\\broll angle\\b",\n        ],\n    ),\n    (\n        "roll_at_trigger",\n        [\n            r"\\broll angle at the time of trg\\b",\n        ],\n    ),\n    (\n        "roll_time_zero_offset",\n        [\n            r"\\broll angle time zero offset\\b",\n        ],\n    ),\n    (\n        "trigger_relative_timing",\n        [\n            r"\\btime from time zero to trg\\b",\n        ],\n    ),\n    (\n        "precrash_time_alignment",\n        [\n            r"\\btime from last speed data sample\\b.*\\btime zero\\b",\n        ],\n    ),\n    (\n        "sensor_loss_timing",\n        [\n            r"\\btime yaw rate lost\\b",\n        ],\n    ),\n    (\n        "direction_summary",\n        [\n            r"\\brecorded side\\b",\n            r"\\bpdof\\b",\n            r"\\bprincipal direction of force\\b",\n            r"\\bcrash direction\\b",\n            r"\\brecorded direction\\b",\n        ],\n    ),\n]\n\n\ndef classify_family(label):\n    text = clean(label)\n\n    for family, patterns in FAMILY_RULES:\n        if any(\n            re.search(\n                pattern,\n                text,\n                re.I,\n            )\n            for pattern in patterns\n        ):\n            return family\n\n    return ""\n\n\n# ============================================================\n# Strong exclusions\n# ============================================================\n\nGROUP3_PATTERNS = [\n    r"\\bair ?bag\\b",\n    r"\\bpretensioner\\b",\n    r"\\bdeployment command\\b",\n    r"\\bdeployment criteria\\b",\n    r"\\b1st stage\\b",\n    r"\\b2nd stage\\b",\n    r"\\bbelt switch\\b",\n    r"\\bseat belt\\b",\n    r"\\boccupant\\b",\n    r"\\bpassenger classification\\b",\n    r"\\bsuppression\\b",\n    r"\\bwarning lamp\\b",\n    r"\\bsir\\b",\n    r"\\bdtc\\b",\n    r"\\bdiagnostic trouble\\b",\n    r"\\bseat position\\b",\n    r"\\brestraint\\b",\n    r"\\bhigh voltage disable\\b",\n    r"\\bpower loss detected during event\\b",\n]\n\nGROUP2_PATTERNS = [\n    r"\\bevent recording complete\\b",\n    r"\\bcrash record locked\\b",\n    r"\\brecording complete\\b",\n    r"\\bmultiple events?\\b",\n    r"\\bevent counter\\b",\n    r"\\bassociated events?\\b",\n    r"\\bevents? not recorded\\b",\n    r"\\btime between\\b.*\\bevents?\\b",\n]\n\nGROUP6_PATTERNS = [\n    r"\\bignition cycles?\\b",\n    r"\\bpart number\\b",\n    r"\\bserial number\\b",\n    r"\\bsoftware version\\b",\n    r"\\bsupplier id\\b",\n    r"\\bproduction date\\b",\n    r"\\bconfiguration\\b",\n    r"\\bvehicle mileage\\b",\n    r"\\bodometer\\b",\n]\n\nGROUP1_PATTERNS = [\n    r"\\bfilename\\b",\n    r"\\bsaved on\\b",\n    r"\\bimaged with\\b",\n    r"\\breported with\\b",\n    r"\\bcrash date\\b",\n    r"\\bedr data imaging date\\b",\n    r"\\buser entered vin\\b",\n    r"\\bdevice type\\b",\n]\n\n\ndef matches_any(text, patterns):\n    return any(\n        re.search(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern in patterns\n    )\n\n\n# ============================================================\n# CSV vocabulary support\n# ============================================================\n\ndef load_csv_label_vocabulary(path: Path):\n    labels = Counter()\n\n    if not path.exists():\n        return labels\n\n    for row in read_csv_dict(path):\n        key = norm_key(\n            row.get(\n                "field_label_raw",\n                "",\n            )\n        )\n\n        if key:\n            labels[key] += 1\n\n    return labels\n\n\n# ============================================================\n# Label/value parsing from PDF lines\n# ============================================================\n\nVALUE_SUFFIX = re.compile(\n    r"^(?P<label>.+?)\\s{2,}(?P<value>\\S(?:.*\\S)?)$"\n)\n\nVALUE_END_PATTERNS = [\n    re.compile(\n        r"^(?P<label>.+?)\\s+"\n        r"(?P<value>"\n        r"[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n        r"(?:\\s*(?:MPH|km/h|kph|m/s|g|"\n        r"msec|ms|sec|seconds?|deg|degrees?|%))?"\n        r")$",\n        re.I,\n    ),\n    re.compile(\n        r"^(?P<label>.+?)\\s+"\n        r"(?P<value>N/A|NA|SNA|Yes|No|Left|Right|Front|Rear)$",\n        re.I,\n    ),\n]\n\n\ndef parse_label_value(line):\n    """\n    Conservative line parser.\n\n    pdfplumber usually preserves several spaces between label/value columns.\n    We try:\n      1. two-or-more spaces\n      2. a numeric/status suffix\n    """\n\n    raw = line.rstrip()\n\n    match = VALUE_SUFFIX.match(raw)\n\n    if match:\n        label = clean(\n            match.group("label")\n        )\n        value = clean(\n            match.group("value")\n        )\n\n        if label and value:\n            return label, value\n\n    for pattern in VALUE_END_PATTERNS:\n        match = pattern.match(\n            clean(raw)\n        )\n\n        if match:\n            label = clean(\n                match.group("label")\n            )\n            value = clean(\n                match.group("value")\n            )\n\n            if label and value:\n                return label, value\n\n    return None\n\n\n# ============================================================\n# Candidate scoring\n# ============================================================\n\ndef score_observation(\n    label,\n    value,\n    section,\n    csv_vocab,\n):\n    family = classify_family(label)\n\n    score = 0\n    evidence = []\n    exclusions = []\n\n    if family:\n        score += 6\n        evidence.append(\n            f"family:{family}"\n        )\n\n    if is_value_like(value):\n        score += 1\n        evidence.append(\n            "scalar_value_like"\n        )\n\n    key = norm_key(label)\n\n    if key in csv_vocab:\n        score += 3\n        evidence.append(\n            "matches_frozen_csv_group5_label"\n        )\n\n    if re.search(\n        r"\\b(?:"\n        r"maximum|max|peak|final|"\n        r"delta[- ]?v|velocity change|"\n        r"acceleration|roll angle|"\n        r"recorded side|pdof|"\n        r"clipping"\n        r")\\b",\n        label,\n        re.I,\n    ):\n        score += 1\n        evidence.append(\n            "crash_measurement_terms"\n        )\n\n    if matches_any(\n        label,\n        GROUP3_PATTERNS,\n    ):\n        exclusions.append(\n            "group3_deployment_or_status"\n        )\n\n    if matches_any(\n        label,\n        GROUP2_PATTERNS,\n    ):\n        exclusions.append(\n            "group2_record_structure"\n        )\n\n    if matches_any(\n        label,\n        GROUP6_PATTERNS,\n    ):\n        exclusions.append(\n            "group6_technical"\n        )\n\n    if matches_any(\n        label,\n        GROUP1_PATTERNS,\n    ):\n        exclusions.append(\n            "group1_report_metadata"\n        )\n\n    if exclusions:\n        decision = "excluded_overlap"\n\n    elif score >= 6:\n        decision = "candidate"\n\n    elif score >= 3:\n        decision = "review"\n\n    else:\n        decision = "not_group5"\n\n    return {\n        "family":\n            family\n            or "other_crash_measurement",\n\n        "score":\n            score,\n\n        "decision":\n            decision,\n\n        "evidence":\n            evidence,\n\n        "exclusions":\n            exclusions,\n\n        "csv_label_support_count":\n            csv_vocab.get(key, 0),\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--report-index",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group1_v4/report_index.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--source-root",\n        type=Path,\n        default=Path("data/temp"),\n    )\n\n    parser.add_argument(\n        "--csv-vocabulary",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_csv_final_v1/"\n            "measurement_registry.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_pdf_discovery_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    if not args.report_index.exists():\n        raise FileNotFoundError(\n            args.report_index\n        )\n\n    report_index = read_csv_dict(\n        args.report_index\n    )\n\n    csv_vocab = load_csv_label_vocabulary(\n        args.csv_vocabulary\n    )\n\n    selected = [\n        row\n        for row in report_index\n        if pdf_only_report(row)\n    ]\n\n    candidates = []\n    reviews = []\n    excluded = []\n    coverage = []\n    errors = []\n\n    family_counter = Counter()\n    label_counter = Counter()\n    section_counter = Counter()\n    decision_counter = Counter()\n\n    reports_with_candidates = set()\n    reports_with_reviews = set()\n\n    for report_number, row in enumerate(\n        selected,\n        1,\n    ):\n        pdf_path = resolve_pdf_path(\n            row,\n            args.source_root,\n        )\n\n        if (\n            pdf_path is None\n            or not pdf_path.exists()\n        ):\n            errors.append({\n                **{\n                    key:\n                        row.get(key, "")\n                    for key in BASE\n                },\n                "error_type":\n                    "pdf_source_not_found",\n                "pdf_path":\n                    row.get(\n                        "pdf_path",\n                        "",\n                    ),\n                "error":\n                    "Could not resolve original PDF source.",\n            })\n\n            coverage.append({\n                **{\n                    key:\n                        row.get(key, "")\n                    for key in BASE\n                },\n                "pdf_path":\n                    row.get(\n                        "pdf_path",\n                        "",\n                    ),\n                "processing_status":\n                    "source_not_found",\n                "candidate_count":\n                    0,\n                "review_count":\n                    0,\n                "excluded_overlap_count":\n                    0,\n            })\n\n            continue\n\n        try:\n            pages = extract_pages(\n                pdf_path\n            )\n\n        except Exception as exc:\n            errors.append({\n                **{\n                    key:\n                        row.get(key, "")\n                    for key in BASE\n                },\n                "error_type":\n                    type(exc).__name__,\n                "pdf_path":\n                    str(pdf_path),\n                "error":\n                    str(exc),\n            })\n\n            coverage.append({\n                **{\n                    key:\n                        row.get(key, "")\n                    for key in BASE\n                },\n                "pdf_path":\n                    str(pdf_path),\n                "processing_status":\n                    "source_error",\n                "candidate_count":\n                    0,\n                "review_count":\n                    0,\n                "excluded_overlap_count":\n                    0,\n            })\n\n            continue\n\n        report_candidates = 0\n        report_reviews = 0\n        report_excluded = 0\n\n        current_section = ""\n\n        for page_number, lines in pages:\n            page_section = current_section\n\n            for line_index, line in enumerate(\n                lines,\n                1,\n            ):\n                detected = detect_section(\n                    line\n                )\n\n                if detected:\n                    current_section = detected\n                    page_section = detected\n\n                parsed = parse_label_value(\n                    line\n                )\n\n                if not parsed:\n                    continue\n\n                label, value = parsed\n\n                result = score_observation(\n                    label=label,\n                    value=value,\n                    section=current_section,\n                    csv_vocab=csv_vocab,\n                )\n\n                if result[\n                    "decision"\n                ] == "not_group5":\n                    continue\n\n                event_hint = extract_event_hint(\n                    current_section,\n                    label,\n                )\n\n                candidate_id = (\n                    "g5pdf_"\n                    + identifier(\n                        row.get(\n                            "report_id",\n                            "",\n                        ),\n                        page_number,\n                        line_index,\n                        label,\n                        value,\n                    )\n                )\n\n                record = {\n                    **{\n                        key:\n                            row.get(key, "")\n                        for key in BASE\n                    },\n\n                    "group5_pdf_candidate_id":\n                        candidate_id,\n\n                    "source_format":\n                        "pdf",\n\n                    "source_path":\n                        str(pdf_path),\n\n                    "source_page_number":\n                        page_number,\n\n                    "source_line_number_on_page":\n                        line_index,\n\n                    "source_section_heading":\n                        current_section,\n\n                    "event_hint":\n                        event_hint,\n\n                    "field_label_raw":\n                        label,\n\n                    "field_value_raw":\n                        value,\n\n                    "source_line_raw":\n                        line,\n\n                    "candidate_family":\n                        result[\n                            "family"\n                        ],\n\n                    "candidate_score":\n                        result[\n                            "score"\n                        ],\n\n                    "discovery_decision":\n                        result[\n                            "decision"\n                        ],\n\n                    "evidence_json":\n                        json.dumps(\n                            result[\n                                "evidence"\n                            ],\n                            ensure_ascii=False,\n                        ),\n\n                    "overlap_exclusions_json":\n                        json.dumps(\n                            result[\n                                "exclusions"\n                            ],\n                            ensure_ascii=False,\n                        ),\n\n                    "csv_label_support_count":\n                        result[\n                            "csv_label_support_count"\n                        ],\n\n                    "semantic_normalization_status":\n                        "not_normalized",\n\n                    "unit_conversion_status":\n                        "not_converted",\n\n                    "event_link_status":\n                        (\n                            "source_hint_only"\n                            if event_hint\n                            else "not_linked"\n                        ),\n                }\n\n                decision_counter[\n                    result[\n                        "decision"\n                    ]\n                ] += 1\n\n                if result[\n                    "decision"\n                ] == "candidate":\n                    candidates.append(\n                        record\n                    )\n\n                    report_candidates += 1\n\n                    reports_with_candidates.add(\n                        row.get(\n                            "report_id",\n                            "",\n                        )\n                    )\n\n                    family_counter[\n                        result[\n                            "family"\n                        ]\n                    ] += 1\n\n                    label_counter[\n                        norm_key(label)\n                    ] += 1\n\n                    section_counter[\n                        clean(\n                            current_section\n                        )\n                        or "<no_section_heading>"\n                    ] += 1\n\n                elif result[\n                    "decision"\n                ] == "review":\n                    reviews.append(\n                        record\n                    )\n\n                    report_reviews += 1\n\n                    reports_with_reviews.add(\n                        row.get(\n                            "report_id",\n                            "",\n                        )\n                    )\n\n                elif result[\n                    "decision"\n                ] == "excluded_overlap":\n                    excluded.append(\n                        record\n                    )\n                    report_excluded += 1\n\n        if report_candidates:\n            status = (\n                "group5_candidates_found"\n            )\n\n        elif report_reviews:\n            status = "review_only"\n\n        else:\n            status = (\n                "no_group5_candidates"\n            )\n\n        coverage.append({\n            **{\n                key:\n                    row.get(key, "")\n                for key in BASE\n            },\n\n            "pdf_path":\n                str(pdf_path),\n\n            "processing_status":\n                status,\n\n            "candidate_count":\n                report_candidates,\n\n            "review_count":\n                report_reviews,\n\n            "excluded_overlap_count":\n                report_excluded,\n        })\n\n        if (\n            report_number % 25 == 0\n            or report_number\n            == len(selected)\n        ):\n            print(\n                "Discovered Group 5 PDF "\n                f"{report_number}/"\n                f"{len(selected)} reports...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    raw_label_examples = defaultdict(\n        Counter\n    )\n\n    for row in candidates:\n        key = norm_key(\n            row[\n                "field_label_raw"\n            ]\n        )\n\n        raw_label_examples[\n            key\n        ][\n            row[\n                "field_label_raw"\n            ]\n        ] += 1\n\n    label_summary = []\n\n    for key, count in (\n        label_counter.most_common()\n    ):\n        label_summary.append({\n            "normalized_label":\n                key,\n\n            "candidate_count":\n                count,\n\n            "raw_label_examples_json":\n                json.dumps(\n                    [\n                        label\n                        for label, _\n                        in raw_label_examples[\n                            key\n                        ].most_common(5)\n                    ],\n                    ensure_ascii=False,\n                ),\n        })\n\n    family_summary = [\n        {\n            "candidate_family":\n                family,\n            "candidate_count":\n                count,\n        }\n        for family, count\n        in family_counter.most_common()\n    ]\n\n    section_summary = [\n        {\n            "source_section_heading":\n                section,\n            "candidate_count":\n                count,\n        }\n        for section, count\n        in section_counter.most_common()\n    ]\n\n    # ========================================================\n    # Write\n    # ========================================================\n\n    out = args.output_directory\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    columns = [\n        *BASE,\n        "group5_pdf_candidate_id",\n        "source_format",\n        "source_path",\n        "source_page_number",\n        "source_line_number_on_page",\n        "source_section_heading",\n        "event_hint",\n        "field_label_raw",\n        "field_value_raw",\n        "source_line_raw",\n        "candidate_family",\n        "candidate_score",\n        "discovery_decision",\n        "evidence_json",\n        "overlap_exclusions_json",\n        "csv_label_support_count",\n        "semantic_normalization_status",\n        "unit_conversion_status",\n        "event_link_status",\n    ]\n\n    write_csv(\n        out\n        / "group5_pdf_candidate_fields.csv",\n        candidates,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_review_fields.csv",\n        reviews,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_excluded_overlap_fields.csv",\n        excluded,\n        columns,\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_report_coverage.csv",\n        coverage,\n        [\n            *BASE,\n            "pdf_path",\n            "processing_status",\n            "candidate_count",\n            "review_count",\n            "excluded_overlap_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_label_summary.csv",\n        label_summary,\n        [\n            "normalized_label",\n            "candidate_count",\n            "raw_label_examples_json",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_family_summary.csv",\n        family_summary,\n        [\n            "candidate_family",\n            "candidate_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "group5_pdf_section_summary.csv",\n        section_summary,\n        [\n            "source_section_heading",\n            "candidate_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "pdf_source_errors.csv",\n        errors,\n        [\n            *BASE,\n            "error_type",\n            "pdf_path",\n            "error",\n        ],\n    )\n\n    coverage_counts = Counter(\n        row[\n            "processing_status"\n        ]\n        for row in coverage\n    )\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "PDF-only discovery",\n\n        "reports_in_index":\n            len(report_index),\n\n        "pdf_only_reports_selected":\n            len(selected),\n\n        "pdf_only_reports_processed":\n            len(coverage)\n            - sum(\n                1\n                for row in coverage\n                if row[\n                    "processing_status"\n                ] in {\n                    "source_not_found",\n                    "source_error",\n                }\n            ),\n\n        "reports_with_group5_candidates":\n            len(\n                reports_with_candidates\n            ),\n\n        "reports_with_review_fields":\n            len(\n                reports_with_reviews\n            ),\n\n        "candidate_field_count":\n            len(candidates),\n\n        "review_field_count":\n            len(reviews),\n\n        "excluded_overlap_field_count":\n            len(excluded),\n\n        "candidate_family_counts":\n            dict(\n                family_counter\n            ),\n\n        "decision_counts":\n            dict(\n                decision_counter\n            ),\n\n        "coverage_status_counts":\n            dict(\n                coverage_counts\n            ),\n\n        "unique_candidate_labels":\n            len(\n                label_counter\n            ),\n\n        "csv_vocabulary_available":\n            args.csv_vocabulary.exists(),\n\n        "csv_vocabulary_label_count":\n            len(\n                csv_vocab\n            ),\n\n        "pdf_source_errors":\n            len(errors),\n\n        "scope":\n            (\n                "PDF-only discovery for Group 5 scalar/non-time-series "\n                "crash and event measurements. Only reports without CSV "\n                "sources are processed. Original PDFs are authoritative. "\n                "The frozen Group 5 CSV package is used only as optional "\n                "label-vocabulary support. Page, line, section, event hint, "\n                "raw label, raw value, and original source line are "\n                "preserved. No OCR, semantic normalization, unit conversion, "\n                "fuzzy event linking, final extraction, or CSV/PDF "\n                "integration is performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 5 PDF DISCOVERY COMPLETE."\n    )\n\n\n'

_PDF_AUDIT_SOURCE = '"""\nAudit Group 5 PDF-only discovery candidates.\n\nInput\n-----\ndata/processed/edr/group5_pdf_discovery_v1/\n    group5_pdf_candidate_fields.csv\n    group5_pdf_review_fields.csv\n    group5_pdf_report_coverage.csv\n\nOutput\n------\ndata/processed/edr/group5_pdf_audit_v1/\n\n    accepted_group5_pdf_fields.csv\n    excluded_pdf_parse_artifacts.csv\n    remaining_review_fields.csv\n    audit_all_fields.csv\n    family_summary.csv\n    label_summary.csv\n    report_summary.csv\n    validation_checks.csv\n    metadata.json\n\nPurpose\n-------\nAudit the 619 PDF discovery candidates before structural extraction.\n\nKey policy\n----------\n- Preserve numeric, N/A/SNA, and explicit "No" values exactly as reported.\n- "Clipping Time ... = No" is retained as source-reported Group 5 evidence.\n  It is not converted to zero or interpreted semantically.\n- Exclude clear PDF line-splitting artifacts such as:\n      Maximum Delta-V, Lateral Left to | Right\n  where "Right" is part of the label phrase "Left to Right", not a value.\n- Preserve page, line, section, event hint, source line, and PDF provenance.\n- Do not normalize values, convert units, or infer event identity.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(path: Path, rows: list[dict], columns: list[str]):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_suffix(path.suffix + ".part")\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value if value is not None else "").strip(),\n    )\n\n\ndef is_numeric(value):\n    text = norm(value).replace(",", "")\n\n    if not text:\n        return False\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef classify_candidate(row):\n    label = norm(row.get("field_label_raw", ""))\n    value = norm(row.get("field_value_raw", ""))\n    source_line = norm(row.get("source_line_raw", ""))\n\n    # Clear PDF parsing artifact:\n    # source phrase is "Maximum Delta-V, Lateral Left to Right"\n    # but generic label/value splitting interpreted "Right" as the value.\n    if (\n        re.search(\n            r"\\bmaximum delta[- ]?v,\\s*lateral left to$",\n            label,\n            re.I,\n        )\n        and value.casefold() == "right"\n        and re.search(\n            r"\\bmaximum delta[- ]?v,\\s*lateral left to right\\b",\n            source_line,\n            re.I,\n        )\n    ):\n        return (\n            "exclude",\n            "pdf_label_split_artifact",\n            "Right is part of the directional label phrase Left to Right.",\n        )\n\n    # All discovered Group 5 candidates otherwise remain accepted.\n    # Explicit No/SNA values are valid source-reported values and are\n    # intentionally preserved rather than forced to numeric.\n    return (\n        "accept",\n        "accepted_group5_pdf_candidate",\n        "Discovery rule and source-line audit support Group 5 membership.",\n    )\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n\n    parser.add_argument(\n        "--discovery-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/group5_pdf_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/group5_pdf_audit_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    cand_path = (\n        args.discovery_directory\n        / "group5_pdf_candidate_fields.csv"\n    )\n    review_path = (\n        args.discovery_directory\n        / "group5_pdf_review_fields.csv"\n    )\n    coverage_path = (\n        args.discovery_directory\n        / "group5_pdf_report_coverage.csv"\n    )\n\n    for path in [\n        cand_path,\n        review_path,\n        coverage_path,\n    ]:\n        if not path.exists():\n            raise FileNotFoundError(path)\n\n    candidates = read_csv(cand_path)\n    discovery_review = read_csv(review_path)\n    coverage = read_csv(coverage_path)\n\n    audited = []\n\n    for row in candidates:\n        decision, status, reason = classify_candidate(row)\n\n        audited.append({\n            **row,\n            "audit_decision": decision,\n            "audit_status": status,\n            "audit_reason": reason,\n        })\n\n    # There were zero discovery review fields in the current package,\n    # but preserve the mechanism in case of reruns.\n    for row in discovery_review:\n        audited.append({\n            **row,\n            "audit_decision": "review",\n            "audit_status": "remaining_review",\n            "audit_reason": "Retained from PDF discovery review population.",\n        })\n\n    accepted = [\n        row\n        for row in audited\n        if row["audit_decision"] == "accept"\n    ]\n\n    excluded = [\n        row\n        for row in audited\n        if row["audit_decision"] == "exclude"\n    ]\n\n    remaining_review = [\n        row\n        for row in audited\n        if row["audit_decision"] == "review"\n    ]\n\n    # --------------------------------------------------------\n    # Validation\n    # --------------------------------------------------------\n\n    checks = []\n\n    def check(\n        name,\n        condition,\n        observed,\n        expected,\n        severity="hard",\n        note="",\n    ):\n        checks.append({\n            "check": name,\n            "status": "PASS" if condition else "FAIL",\n            "severity": severity,\n            "observed": str(observed),\n            "expected": str(expected),\n            "note": note,\n        })\n\n    check(\n        "input_candidate_count",\n        len(candidates) == 619,\n        len(candidates),\n        619,\n        severity="warning",\n    )\n\n    check(\n        "discovery_review_count",\n        len(discovery_review) == 0,\n        len(discovery_review),\n        0,\n        severity="warning",\n    )\n\n    check(\n        "all_candidate_rows_accounted_for",\n        (\n            len(accepted)\n            + len(excluded)\n            + len(remaining_review)\n            == len(candidates)\n            + len(discovery_review)\n        ),\n        (\n            len(accepted)\n            + len(excluded)\n            + len(remaining_review)\n        ),\n        (\n            len(candidates)\n            + len(discovery_review)\n        ),\n    )\n\n    ids = [\n        norm(row.get("group5_pdf_candidate_id", ""))\n        for row in accepted\n    ]\n\n    check(\n        "accepted_candidate_ids_unique",\n        len(ids) == len(set(ids)),\n        len(ids) - len(set(ids)),\n        0,\n    )\n\n    blank_labels = sum(\n        1\n        for row in accepted\n        if not norm(row.get("field_label_raw", ""))\n    )\n\n    blank_values = sum(\n        1\n        for row in accepted\n        if not norm(row.get("field_value_raw", ""))\n    )\n\n    check(\n        "blank_accepted_labels",\n        blank_labels == 0,\n        blank_labels,\n        0,\n    )\n\n    check(\n        "blank_accepted_values",\n        blank_values == 0,\n        blank_values,\n        0,\n    )\n\n    provenance_missing = sum(\n        1\n        for row in accepted\n        if (\n            not norm(row.get("source_path", ""))\n            or not norm(row.get("source_page_number", ""))\n            or not norm(row.get("source_line_number_on_page", ""))\n            or not norm(row.get("source_line_raw", ""))\n        )\n    )\n\n    check(\n        "accepted_provenance_complete",\n        provenance_missing == 0,\n        provenance_missing,\n        0,\n    )\n\n    # The only expected clear parse artifacts in this current discovery\n    # are the two "Left to Right" rows.\n    left_to_right_artifacts = sum(\n        1\n        for row in excluded\n        if row["audit_status"]\n        == "pdf_label_split_artifact"\n    )\n\n    check(\n        "expected_left_to_right_parse_artifacts",\n        left_to_right_artifacts == 2,\n        left_to_right_artifacts,\n        2,\n        severity="warning",\n    )\n\n    # --------------------------------------------------------\n    # Summaries\n    # --------------------------------------------------------\n\n    family_counter = Counter(\n        row.get("candidate_family", "")\n        for row in accepted\n    )\n\n    label_counter = Counter(\n        norm(row.get("field_label_raw", ""))\n        for row in accepted\n    )\n\n    report_counter = Counter(\n        row.get("report_id", "")\n        for row in accepted\n    )\n\n    family_summary = [\n        {\n            "candidate_family": family,\n            "accepted_field_count": count,\n            "report_count": len({\n                row.get("report_id", "")\n                for row in accepted\n                if row.get("candidate_family", "") == family\n            }),\n        }\n        for family, count\n        in family_counter.most_common()\n    ]\n\n    label_summary = [\n        {\n            "field_label_raw": label,\n            "accepted_field_count": count,\n        }\n        for label, count\n        in label_counter.most_common()\n    ]\n\n    coverage_by_report = {\n        row.get("report_id", ""): row\n        for row in coverage\n    }\n\n    report_summary = []\n\n    for report_id, count in report_counter.items():\n        c = coverage_by_report.get(\n            report_id,\n            {},\n        )\n\n        report_summary.append({\n            "report_id": report_id,\n            "case_id": c.get("case_id", ""),\n            "vehicle_number": c.get("vehicle_number", ""),\n            "export_basename": c.get("export_basename", ""),\n            "accepted_group5_pdf_fields": count,\n        })\n\n    # --------------------------------------------------------\n    # Write\n    # --------------------------------------------------------\n\n    out = args.output_directory\n    out.mkdir(parents=True, exist_ok=True)\n\n    columns = list(audited[0].keys()) if audited else []\n\n    write_csv(\n        out / "accepted_group5_pdf_fields.csv",\n        accepted,\n        columns,\n    )\n\n    write_csv(\n        out / "excluded_pdf_parse_artifacts.csv",\n        excluded,\n        columns,\n    )\n\n    write_csv(\n        out / "remaining_review_fields.csv",\n        remaining_review,\n        columns,\n    )\n\n    write_csv(\n        out / "audit_all_fields.csv",\n        audited,\n        columns,\n    )\n\n    write_csv(\n        out / "family_summary.csv",\n        family_summary,\n        [\n            "candidate_family",\n            "accepted_field_count",\n            "report_count",\n        ],\n    )\n\n    write_csv(\n        out / "label_summary.csv",\n        label_summary,\n        [\n            "field_label_raw",\n            "accepted_field_count",\n        ],\n    )\n\n    write_csv(\n        out / "report_summary.csv",\n        report_summary,\n        [\n            "report_id",\n            "case_id",\n            "vehicle_number",\n            "export_basename",\n            "accepted_group5_pdf_fields",\n        ],\n    )\n\n    write_csv(\n        out / "validation_checks.csv",\n        checks,\n        [\n            "check",\n            "status",\n            "severity",\n            "observed",\n            "expected",\n            "note",\n        ],\n    )\n\n    hard_failures = [\n        row\n        for row in checks\n        if (\n            row["status"] == "FAIL"\n            and row["severity"] == "hard"\n        )\n    ]\n\n    warning_failures = [\n        row\n        for row in checks\n        if (\n            row["status"] == "FAIL"\n            and row["severity"] == "warning"\n        )\n    ]\n\n    explicit_no_count = sum(\n        1\n        for row in accepted\n        if norm(\n            row.get("field_value_raw", "")\n        ).casefold() == "no"\n    )\n\n    sna_count = sum(\n        1\n        for row in accepted\n        if norm(\n            row.get("field_value_raw", "")\n        ).casefold() == "sna"\n    )\n\n    numeric_count = sum(\n        1\n        for row in accepted\n        if is_numeric(\n            row.get("field_value_raw", "")\n        )\n    )\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "PDF-only candidate audit",\n\n        "input_candidate_fields":\n            len(candidates),\n\n        "input_review_fields":\n            len(discovery_review),\n\n        "accepted_group5_pdf_fields":\n            len(accepted),\n\n        "excluded_pdf_parse_artifacts":\n            len(excluded),\n\n        "remaining_review_fields":\n            len(remaining_review),\n\n        "reports_with_accepted_group5_pdf_fields":\n            len(report_counter),\n\n        "accepted_family_counts":\n            dict(family_counter),\n\n        "numeric_raw_value_count":\n            numeric_count,\n\n        "explicit_no_value_count":\n            explicit_no_count,\n\n        "sna_value_count":\n            sna_count,\n\n        "validation_checks":\n            len(checks),\n\n        "hard_validation_failures":\n            len(hard_failures),\n\n        "warning_validation_failures":\n            len(warning_failures),\n\n        "scope":\n            (\n                "Audit of Group 5 PDF-only discovery candidates. "\n                "Clear PDF line-splitting artifacts are excluded. "\n                "Explicit No and SNA values in clipping-time fields are "\n                "preserved exactly as source-reported evidence rather than "\n                "converted or semantically interpreted. Page/line/source "\n                "provenance remains intact. No unit conversion, semantic "\n                "normalization, OCR, fuzzy event linking, or final "\n                "structural extraction is performed."\n            ),\n    }\n\n    tmp = out / "metadata.json.part"\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(out / "metadata.json")\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(f"Outputs: {out}")\n\n    if hard_failures:\n        print()\n        print(\n            "GROUP 5 PDF AUDIT HAS HARD VALIDATION FAILURES."\n        )\n        raise SystemExit(1)\n\n    print()\n    print(\n        "GROUP 5 PDF AUDIT COMPLETE."\n    )\n\n\n'

_PDF_EXTRACT_SOURCE = '"""\nBuild structured Group 5 PDF-only scalar crash/event measurement datasets.\n\nInput\n-----\ndata/processed/edr/group5_pdf_audit_v1/\n    accepted_group5_pdf_fields.csv\n\nOutput\n------\ndata/processed/edr/group5_pdf_structured_v1/\n\n    measurement_registry.csv\n    measurement_values.csv\n    extraction_audit.csv\n    extraction_failures.csv\n    validation_report.csv\n    metadata.json\n\nPurpose\n-------\nConvert the audited Group 5 PDF-only field population into a structured scalar\nmeasurement package while preserving original PDF provenance.\n\nImportant rules\n---------------\n- One accepted PDF source field becomes one measurement record.\n- Preserve raw label/value/page/line/section/source line exactly.\n- Parse numeric values only when safely recoverable.\n- Infer raw units conservatively from label/value.\n- Preserve explicit No/SNA/N/A values as source-reported evidence.\n- No semantic normalization.\n- No unit conversion.\n- No OCR.\n- No fuzzy event identity inference.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nimport re\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        errors="replace",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# Helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value if value is not None else "").strip(),\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode("utf-8")\n    ).hexdigest()[:24]\n\n\nMISSING_VALUES = {\n    "",\n    "n/a",\n    "na",\n    "sna",\n    "not available",\n    "data not available",\n    "not applicable",\n    "unknown",\n    "invalid",\n    "not recorded",\n}\n\n\ndef is_missing_or_na(value):\n    return norm(value).casefold() in MISSING_VALUES\n\n\n# ============================================================\n# Units\n# ============================================================\n\nUNIT_PATTERNS = [\n    ("mph", r"\\bmph\\b"),\n    ("km/h", r"\\bkm/h\\b|\\bkph\\b"),\n    ("m/s", r"\\bm/s\\b"),\n    ("m/s^2", r"\\bm/s(?:\\^?2|²)\\b"),\n    ("ft/s^2", r"\\bft/s(?:\\^?2|²)\\b"),\n    ("g", r"(?<![a-z])g(?![a-z])"),\n    ("ms", r"\\bmsec\\b|\\bmilliseconds?\\b|\\bms\\b"),\n    ("s", r"\\bseconds?\\b|\\bsec\\b"),\n    ("deg", r"\\bdegrees?\\b|\\bdeg\\b"),\n    ("deg/s", r"\\bdeg/s\\b|\\bdegrees?/sec\\b"),\n    ("rad/s", r"\\brad/s\\b"),\n    ("%", r"%|\\bpercent\\b"),\n]\n\n\ndef extract_unit(label, value):\n    label_text = norm(label)\n    value_text = norm(value)\n\n    for content in reversed(\n        re.findall(\n            r"\\(([^()]*)\\)",\n            label_text,\n        )\n    ):\n        candidate = norm(content)\n\n        for _, pattern in UNIT_PATTERNS:\n            if re.search(\n                pattern,\n                candidate,\n                re.I,\n            ):\n                return candidate\n\n    for _, pattern in UNIT_PATTERNS:\n        match = re.search(\n            pattern,\n            label_text,\n            re.I,\n        )\n\n        if match:\n            return norm(\n                match.group(0)\n            )\n\n    for _, pattern in UNIT_PATTERNS:\n        match = re.search(\n            pattern,\n            value_text,\n            re.I,\n        )\n\n        if match:\n            return norm(\n                match.group(0)\n            )\n\n    return ""\n\n\n# ============================================================\n# Numeric parsing\n# ============================================================\n\nNUMERIC_PATTERN = re.compile(\n    r"[-+]?"\n    r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n    r"(?:[eE][-+]?\\d+)?"\n)\n\n\ndef parse_numeric(value):\n    text = norm(value)\n\n    if not text:\n        return ""\n\n    if is_missing_or_na(text):\n        return ""\n\n    # Explicit source-reported status value; preserve only as text.\n    if text.casefold() in {\n        "yes",\n        "no",\n        "left",\n        "right",\n        "front",\n        "rear",\n        "frontal",\n        "side",\n        "rollover",\n    }:\n        return ""\n\n    cleaned = text.replace(",", "")\n\n    cleaned = re.sub(\n        r"\\s*(?:"\n        r"mph|km/h|kph|m/s|m/s\\^?2|m/s²|"\n        r"ft/s\\^?2|ft/s²|g|"\n        r"ms|msec|milliseconds?|"\n        r"sec|seconds?|"\n        r"deg|degrees?|deg/s|rad/s|"\n        r"%|percent"\n        r")\\s*$",\n        "",\n        cleaned,\n        flags=re.I,\n    )\n\n    cleaned = norm(cleaned)\n\n    if not re.fullmatch(\n        NUMERIC_PATTERN,\n        cleaned,\n    ):\n        return ""\n\n    try:\n        number = float(cleaned)\n\n        if math.isfinite(number):\n            return number\n\n    except ValueError:\n        pass\n\n    return ""\n\n\n# ============================================================\n# Record builder\n# ============================================================\n\ndef build_measurement(source):\n    candidate_id = norm(\n        source.get(\n            "group5_pdf_candidate_id",\n            ""\n        )\n    )\n\n    if not candidate_id:\n        raise ValueError(\n            "Missing group5_pdf_candidate_id."\n        )\n\n    label = norm(\n        source.get(\n            "field_label_raw",\n            ""\n        )\n    )\n\n    if not label:\n        raise ValueError(\n            "Missing field_label_raw."\n        )\n\n    raw_value = norm(\n        source.get(\n            "field_value_raw",\n            ""\n        )\n    )\n\n    measurement_id = (\n        "g5pdfmeas_"\n        + identifier(\n            source.get("report_id", ""),\n            candidate_id,\n            source.get(\n                "source_page_number",\n                ""\n            ),\n            source.get(\n                "source_line_number_on_page",\n                ""\n            ),\n            label,\n            raw_value,\n        )\n    )\n\n    numeric = parse_numeric(\n        raw_value\n    )\n\n    unit = extract_unit(\n        label,\n        raw_value,\n    )\n\n    return {\n        **{\n            key:\n                source.get(key, "")\n            for key in BASE\n        },\n\n        "measurement_id":\n            measurement_id,\n\n        "group5_pdf_candidate_id":\n            candidate_id,\n\n        "source_format":\n            "pdf",\n\n        "source_path":\n            source.get(\n                "source_path",\n                "",\n            ),\n\n        "source_page_number":\n            source.get(\n                "source_page_number",\n                "",\n            ),\n\n        "source_line_number_on_page":\n            source.get(\n                "source_line_number_on_page",\n                "",\n            ),\n\n        "source_section_heading":\n            source.get(\n                "source_section_heading",\n                "",\n            ),\n\n        "event_hint":\n            source.get(\n                "event_hint",\n                "",\n            ),\n\n        "event_link_status":\n            source.get(\n                "event_link_status",\n                "",\n            )\n            or "not_linked",\n\n        "family":\n            source.get(\n                "candidate_family",\n                "",\n            ),\n\n        "field_label_raw":\n            label,\n\n        "field_value_raw":\n            raw_value,\n\n        "field_value_numeric":\n            numeric,\n\n        "field_value_is_missing_or_na":\n            is_missing_or_na(\n                raw_value\n            ),\n\n        "unit_raw":\n            unit,\n\n        "source_line_raw":\n            source.get(\n                "source_line_raw",\n                "",\n            ),\n\n        "csv_label_support_count":\n            source.get(\n                "csv_label_support_count",\n                "",\n            ),\n\n        "processing_status":\n            "structured_extracted",\n\n        "semantic_normalization_status":\n            "not_normalized",\n\n        "unit_conversion_status":\n            "not_converted",\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--audit-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_pdf_audit_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group5_pdf_structured_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    accepted_path = (\n        args.audit_directory\n        / "accepted_group5_pdf_fields.csv"\n    )\n\n    if not accepted_path.exists():\n        raise FileNotFoundError(\n            accepted_path\n        )\n\n    accepted = read_csv(\n        accepted_path\n    )\n\n    measurements = []\n    audit_rows = []\n    failures = []\n\n    for index, source in enumerate(\n        accepted,\n        1,\n    ):\n        try:\n            record = build_measurement(\n                source\n            )\n\n            measurements.append(\n                record\n            )\n\n            audit_rows.append({\n                **{\n                    key:\n                        source.get(key, "")\n                    for key in BASE\n                },\n\n                "group5_pdf_candidate_id":\n                    source.get(\n                        "group5_pdf_candidate_id",\n                        "",\n                    ),\n\n                "measurement_id":\n                    record[\n                        "measurement_id"\n                    ],\n\n                "family":\n                    record["family"],\n\n                "field_label_raw":\n                    record[\n                        "field_label_raw"\n                    ],\n\n                "field_value_raw":\n                    record[\n                        "field_value_raw"\n                    ],\n\n                "field_value_numeric":\n                    record[\n                        "field_value_numeric"\n                    ],\n\n                "unit_raw":\n                    record[\n                        "unit_raw"\n                    ],\n\n                "status":\n                    "success",\n\n                "issue":\n                    "",\n            })\n\n        except Exception as exc:\n            failures.append({\n                **{\n                    key:\n                        source.get(key, "")\n                    for key in BASE\n                },\n\n                "group5_pdf_candidate_id":\n                    source.get(\n                        "group5_pdf_candidate_id",\n                        "",\n                    ),\n\n                "field_label_raw":\n                    source.get(\n                        "field_label_raw",\n                        "",\n                    ),\n\n                "field_value_raw":\n                    source.get(\n                        "field_value_raw",\n                        "",\n                    ),\n\n                "error_type":\n                    type(exc).__name__,\n\n                "error":\n                    str(exc),\n            })\n\n        if (\n            index % 100 == 0\n            or index == len(accepted)\n        ):\n            print(\n                "Structured Group 5 PDF "\n                f"{index}/{len(accepted)} fields...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    validation = []\n\n    def check(\n        name,\n        condition,\n        observed,\n        expected,\n        severity="hard",\n        note="",\n    ):\n        validation.append({\n            "check": name,\n            "status":\n                "PASS"\n                if condition\n                else "FAIL",\n            "severity":\n                severity,\n            "observed":\n                str(observed),\n            "expected":\n                str(expected),\n            "note":\n                note,\n        })\n\n    check(\n        "accepted_fields_accounted_for",\n        (\n            len(measurements)\n            + len(failures)\n            == len(accepted)\n        ),\n        (\n            len(measurements)\n            + len(failures)\n        ),\n        len(accepted),\n    )\n\n    check(\n        "expected_input_accepted_count",\n        len(accepted) == 617,\n        len(accepted),\n        617,\n        severity="warning",\n    )\n\n    measurement_ids = [\n        row["measurement_id"]\n        for row in measurements\n    ]\n\n    duplicate_measurement_ids = (\n        len(measurement_ids)\n        - len(set(measurement_ids))\n    )\n\n    check(\n        "measurement_ids_unique",\n        duplicate_measurement_ids == 0,\n        duplicate_measurement_ids,\n        0,\n    )\n\n    candidate_ids = [\n        row["group5_pdf_candidate_id"]\n        for row in measurements\n    ]\n\n    duplicate_candidate_ids = (\n        len(candidate_ids)\n        - len(set(candidate_ids))\n    )\n\n    check(\n        "candidate_ids_unique",\n        duplicate_candidate_ids == 0,\n        duplicate_candidate_ids,\n        0,\n    )\n\n    blank_labels = sum(\n        1\n        for row in measurements\n        if not norm(\n            row["field_label_raw"]\n        )\n    )\n\n    check(\n        "blank_field_labels",\n        blank_labels == 0,\n        blank_labels,\n        0,\n    )\n\n    blank_values = sum(\n        1\n        for row in measurements\n        if not norm(\n            row["field_value_raw"]\n        )\n    )\n\n    check(\n        "blank_field_values",\n        blank_values == 0,\n        blank_values,\n        0,\n    )\n\n    blank_families = sum(\n        1\n        for row in measurements\n        if not norm(\n            row["family"]\n        )\n    )\n\n    check(\n        "blank_families",\n        blank_families == 0,\n        blank_families,\n        0,\n    )\n\n    provenance_missing = sum(\n        1\n        for row in measurements\n        if (\n            not norm(\n                row["source_path"]\n            )\n            or not norm(\n                row["source_page_number"]\n            )\n            or not norm(\n                row[\n                    "source_line_number_on_page"\n                ]\n            )\n            or not norm(\n                row["source_line_raw"]\n            )\n        )\n    )\n\n    check(\n        "pdf_provenance_complete",\n        provenance_missing == 0,\n        provenance_missing,\n        0,\n    )\n\n    family_counts = Counter(\n        row["family"]\n        for row in measurements\n    )\n\n    expected_families = {\n        "delta_v_summary",\n        "delta_v_timing",\n        "trigger_relative_timing",\n        "range_clipping_timing",\n        "delta_v_duration",\n        "roll_peak",\n        "roll_at_trigger",\n        "precrash_time_alignment",\n    }\n\n    unexpected_families = sorted(\n        family\n        for family\n        in family_counts\n        if family\n        not in expected_families\n    )\n\n    check(\n        "unexpected_family_count",\n        len(\n            unexpected_families\n        )\n        == 0,\n        len(\n            unexpected_families\n        ),\n        0,\n        severity="warning",\n        note=json.dumps(\n            unexpected_families,\n            ensure_ascii=False,\n        ),\n    )\n\n    # ========================================================\n    # Write\n    # ========================================================\n\n    out = args.output_directory\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    registry_columns = [\n        *BASE,\n        "measurement_id",\n        "group5_pdf_candidate_id",\n        "source_format",\n        "source_path",\n        "source_page_number",\n        "source_line_number_on_page",\n        "source_section_heading",\n        "event_hint",\n        "event_link_status",\n        "family",\n        "field_label_raw",\n        "field_value_raw",\n        "field_value_numeric",\n        "field_value_is_missing_or_na",\n        "unit_raw",\n        "source_line_raw",\n        "csv_label_support_count",\n        "processing_status",\n        "semantic_normalization_status",\n        "unit_conversion_status",\n    ]\n\n    write_csv(\n        out\n        / "measurement_registry.csv",\n        measurements,\n        registry_columns,\n    )\n\n    write_csv(\n        out\n        / "measurement_values.csv",\n        measurements,\n        registry_columns,\n    )\n\n    write_csv(\n        out\n        / "extraction_audit.csv",\n        audit_rows,\n        [\n            *BASE,\n            "group5_pdf_candidate_id",\n            "measurement_id",\n            "family",\n            "field_label_raw",\n            "field_value_raw",\n            "field_value_numeric",\n            "unit_raw",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "extraction_failures.csv",\n        failures,\n        [\n            *BASE,\n            "group5_pdf_candidate_id",\n            "field_label_raw",\n            "field_value_raw",\n            "error_type",\n            "error",\n        ],\n    )\n\n    write_csv(\n        out\n        / "validation_report.csv",\n        validation,\n        [\n            "check",\n            "status",\n            "severity",\n            "observed",\n            "expected",\n            "note",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    reports_with_measurements = {\n        row["report_id"]\n        for row in measurements\n        if norm(\n            row["report_id"]\n        )\n    }\n\n    cases_with_measurements = {\n        row["case_id"]\n        for row in measurements\n        if norm(\n            row["case_id"]\n        )\n    }\n\n    numeric_count = sum(\n        1\n        for row in measurements\n        if row[\n            "field_value_numeric"\n        ] != ""\n    )\n\n    missing_count = sum(\n        1\n        for row in measurements\n        if row[\n            "field_value_is_missing_or_na"\n        ]\n    )\n\n    explicit_no_count = sum(\n        1\n        for row in measurements\n        if norm(\n            row[\n                "field_value_raw"\n            ]\n        ).casefold()\n        == "no"\n    )\n\n    unit_count = sum(\n        1\n        for row in measurements\n        if norm(\n            row["unit_raw"]\n        )\n    )\n\n    hard_failures = [\n        row\n        for row in validation\n        if (\n            row["status"] == "FAIL"\n            and row["severity"]\n            == "hard"\n        )\n    ]\n\n    warning_failures = [\n        row\n        for row in validation\n        if (\n            row["status"] == "FAIL"\n            and row["severity"]\n            == "warning"\n        )\n    ]\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 5 - Non-time-series crash and event measurements",\n\n        "stage":\n            "PDF-only structural extraction",\n\n        "input_accepted_fields":\n            len(accepted),\n\n        "structured_measurement_count":\n            len(measurements),\n\n        "extraction_failure_count":\n            len(failures),\n\n        "reports_with_structured_measurements":\n            len(\n                reports_with_measurements\n            ),\n\n        "cases_with_structured_measurements":\n            len(\n                cases_with_measurements\n            ),\n\n        "family_counts":\n            dict(\n                family_counts\n            ),\n\n        "numeric_value_count":\n            numeric_count,\n\n        "missing_or_unavailable_value_count":\n            missing_count,\n\n        "explicit_no_value_count":\n            explicit_no_count,\n\n        "measurement_rows_with_raw_unit":\n            unit_count,\n\n        "unique_raw_field_labels":\n            len({\n                row["field_label_raw"]\n                for row in measurements\n            }),\n\n        "validation_checks":\n            len(validation),\n\n        "validation_failures":\n            sum(\n                1\n                for row in validation\n                if row["status"]\n                == "FAIL"\n            ),\n\n        "hard_validation_failures":\n            len(\n                hard_failures\n            ),\n\n        "warning_validation_failures":\n            len(\n                warning_failures\n            ),\n\n        "scope":\n            (\n                "Structural extraction of audited Group 5 PDF-only "\n                "scalar crash/event measurements. Each accepted PDF field "\n                "is preserved as one measurement with report/case/vehicle "\n                "linkage, page/line/source-line provenance, section, "\n                "event hint, raw label, raw value, conservatively parsed "\n                "numeric value, and raw unit. Explicit No/SNA/N/A values "\n                "remain source-reported text/status evidence. No semantic "\n                "normalization, unit conversion, OCR, fuzzy event linking, "\n                "or CSV/PDF integration is performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    if hard_failures:\n        print()\n        print(\n            "GROUP 5 PDF STRUCTURAL EXTRACTION "\n            "HAS HARD VALIDATION FAILURES."\n        )\n        raise SystemExit(1)\n\n    print()\n    print(\n        "GROUP 5 PDF STRUCTURAL EXTRACTION COMPLETE."\n    )\n\n\n'

_CSV_DISCOVERY = _make_ns("csv_discovery", _CSV_DISCOVERY_SOURCE)
_CSV_AUDIT = _make_ns("csv_audit", _CSV_AUDIT_SOURCE)
_CSV_RESOLVE = _make_ns("csv_resolve", _CSV_RESOLVE_SOURCE)
_CSV_EXTRACT = _make_ns("csv_extract", _CSV_EXTRACT_SOURCE)
_PDF_DISCOVERY = _make_ns("pdf_discovery", _PDF_DISCOVERY_SOURCE)
_PDF_AUDIT = _make_ns("pdf_audit", _PDF_AUDIT_SOURCE)
_PDF_EXTRACT = _make_ns("pdf_extract", _PDF_EXTRACT_SOURCE)

DEFAULT_GROUP4_COMPANION = Path(
    "data/processed/edr/group4_final_v1/timeseries_companion_metadata.csv"
)

DEFAULT_GROUP5_CSV_VOCAB = Path(
    "data/processed/edr/group5_csv_final_v1/measurement_registry.csv"
)


def _identity(identity: dict[str, Any]) -> dict[str, str]:
    return {
        "report_id": str(identity.get("report_id", "") or ""),
        "case_id": str(identity.get("case_id", "") or ""),
        "vehicle_number": str(identity.get("vehicle_number", "") or ""),
        "export_basename": str(identity.get("export_basename", "") or ""),
    }


def select_group5_source(csv_path=None, pdf_path=None):
    csv_path = Path(csv_path) if csv_path else None
    pdf_path = Path(pdf_path) if pdf_path else None

    if csv_path and csv_path.is_file():
        return "csv", csv_path

    if pdf_path and pdf_path.is_file():
        return "pdf", pdf_path

    raise FileNotFoundError("No usable CSV or PDF source was found.")


def _load_csv_companion_support(path=None):
    path = Path(path) if path else DEFAULT_GROUP4_COMPANION

    if not path.is_file():
        return {}

    return _CSV_DISCOVERY["load_companion_label_support"](path)


def _load_pdf_csv_vocabulary(path=None):
    path = Path(path) if path else DEFAULT_GROUP5_CSV_VOCAB

    if not path.is_file():
        return set()

    return _PDF_DISCOVERY["load_csv_label_vocabulary"](path)


def _csv_discover(
    path: Path,
    identity: dict[str, Any],
    companion_support_path=None,
):
    base = _identity(identity)
    rows = _CSV_DISCOVERY["read_raw_csv"](path)
    support = _load_csv_companion_support(
        companion_support_path
    )

    candidates = []
    reviews = []
    excluded = []

    current_section = ""

    for row_index, row in rows:

        if _CSV_DISCOVERY["is_heading_row"](row):
            current_section = (
                _CSV_DISCOVERY["populated"](row)[0]
            )
            continue

        parsed = _CSV_DISCOVERY[
            "parse_scalar_observation"
        ](row)

        if parsed is None:
            continue

        label = parsed["label"]
        value = parsed["value"]

        if _CSV_DISCOVERY[
            "looks_like_timeseries_axis"
        ](label):
            continue

        result = _CSV_DISCOVERY["score_field"](
            label=label,
            value=value,
            section_heading=current_section,
            companion_support=support,
        )

        decision = result["decision"]

        if decision == "not_group5":
            continue

        event_hint = _CSV_DISCOVERY[
            "extract_event_hint"
        ](
            current_section,
            label,
        )

        candidate_id = (
            "g5csv_"
            + _CSV_DISCOVERY["identifier"](
                base["report_id"],
                row_index,
                label,
                value,
            )
        )

        obs = {
            **base,
            "group5_candidate_id":
                candidate_id,
            "source_format":
                "csv",
            "source_path":
                str(path),
            "source_record_index":
                row_index,
            "source_section_heading":
                current_section,
            "event_hint":
                event_hint,
            "field_label_raw":
                label,
            "field_value_raw":
                value,
            "value_column_index":
                parsed["value_index"],
            "populated_cell_count":
                parsed["populated_cell_count"],
            "source_row_json":
                json.dumps(
                    row,
                    ensure_ascii=False,
                ),
            "candidate_family":
                result["family"],
            "candidate_score":
                result["score"],
            "discovery_decision":
                decision,
            "evidence_json":
                json.dumps(
                    result["evidence"],
                    ensure_ascii=False,
                ),
            "overlap_exclusions_json":
                json.dumps(
                    result["exclusions"],
                    ensure_ascii=False,
                ),
            "group4_companion_support_count":
                result[
                    "group4_companion_support_count"
                ],
            "semantic_normalization_status":
                "not_normalized",
            "unit_conversion_status":
                "not_converted",
            "event_link_status":
                (
                    "source_hint_only"
                    if event_hint
                    else "not_linked"
                ),
        }

        if decision == "candidate":
            candidates.append(obs)
        elif decision == "review":
            reviews.append(obs)
        elif decision == "excluded_overlap":
            excluded.append(obs)

    return candidates, reviews, excluded


def extract_group5_csv(
    path,
    identity,
    *,
    companion_support_path=None,
):
    path = Path(path)

    candidates, reviews, discovery_excluded = (
        _csv_discover(
            path,
            identity,
            companion_support_path,
        )
    )

    accepted = []
    companions = []
    excluded = list(discovery_excluded)
    unresolved = []

    for row in candidates:
        audited = _CSV_AUDIT[
            "audit_candidate"
        ](row)

        decision = audited[
            "audit_decision"
        ]

        if decision == "accept":
            accepted.append(audited)
        elif decision == "companion":
            companions.append(audited)
        elif decision == "exclude":
            excluded.append(audited)
        else:
            unresolved.append(audited)

    for row in reviews:
        audited = _CSV_AUDIT[
            "audit_review"
        ](row)

        decision = audited[
            "audit_decision"
        ]

        if decision == "accept":
            accepted.append(audited)
        elif decision == "companion":
            companions.append(audited)
        elif decision == "exclude":
            excluded.append(audited)
        else:
            unresolved.append(audited)

    # Apply the validated targeted family correction
    # to all already accepted rows.
    corrected = []

    for row in accepted:
        resolved, _ = _CSV_RESOLVE[
            "reclassify_accepted"
        ](row)
        corrected.append(resolved)

    accepted = corrected

    # Resolve the historical residual review population.
    still_unresolved = []

    for row in unresolved:
        resolved = _CSV_RESOLVE[
            "resolve_review"
        ](row)

        if (
            resolved.get(
                "resolution_decision",
                "",
            )
            == "exclude"
        ):
            excluded.append(resolved)
        else:
            still_unresolved.append(
                resolved
            )

    unresolved = still_unresolved

    measurements = []
    values = []
    issues = []

    for source in accepted:
        try:
            measurement = (
                _CSV_EXTRACT[
                    "build_measurement"
                ](source)
            )
            measurements.append(
                measurement
            )
            # Historical Group 5 writes the same structured
            # measurement rows to measurement_values.csv.
            values.append(
                dict(measurement)
            )

        except Exception as exc:
            issues.append(
                f"{source.get('report_id','')} | "
                f"{source.get('field_label_raw','')} | "
                f"{type(exc).__name__}: {exc}"
            )

    companion_context = []

    for source in companions:
        try:
            companion_context.append(
                _CSV_EXTRACT[
                    "build_companion"
                ](source)
            )
        except Exception as exc:
            issues.append(
                f"{source.get('report_id','')} | "
                f"companion | "
                f"{type(exc).__name__}: {exc}"
            )

    return Group5ExtractionResult(
        source_format="csv",
        source_path=str(path),
        measurements=measurements,
        values=values,
        companion_context=companion_context,
        excluded=excluded,
        unresolved=unresolved,
        issues=issues,
    )


def _pdf_discover(
    path: Path,
    identity: dict[str, Any],
    csv_vocabulary_path=None,
):
    base = _identity(identity)
    vocab = _load_pdf_csv_vocabulary(
        csv_vocabulary_path
    )

    pages = _PDF_DISCOVERY[
        "extract_pages"
    ](path)

    candidates = []
    reviews = []
    excluded = []

    current_section = ""

    for page_number, lines in pages:

        for line_index, line in enumerate(
            lines,
            1,
        ):
            detected = _PDF_DISCOVERY[
                "detect_section"
            ](line)

            if detected:
                current_section = detected

            parsed = _PDF_DISCOVERY[
                "parse_label_value"
            ](line)

            if not parsed:
                continue

            label, value = parsed

            result = _PDF_DISCOVERY[
                "score_observation"
            ](
                label=label,
                value=value,
                section=current_section,
                csv_vocab=vocab,
            )

            decision = result["decision"]

            if decision == "not_group5":
                continue

            event_hint = _PDF_DISCOVERY[
                "extract_event_hint"
            ](
                current_section,
                label,
            )

            candidate_id = (
                "g5pdf_"
                + _PDF_DISCOVERY[
                    "identifier"
                ](
                    base["report_id"],
                    page_number,
                    line_index,
                    label,
                    value,
                )
            )

            obs = {
                **base,
                "group5_pdf_candidate_id":
                    candidate_id,
                "source_format":
                    "pdf",
                "source_path":
                    str(path),
                "source_page_number":
                    page_number,
                "source_line_number_on_page":
                    line_index,
                "source_section_heading":
                    current_section,
                "event_hint":
                    event_hint,
                "field_label_raw":
                    label,
                "field_value_raw":
                    value,
                "source_line_raw":
                    line,
                "candidate_family":
                    result["family"],
                "candidate_score":
                    result["score"],
                "discovery_decision":
                    decision,
                "evidence_json":
                    json.dumps(
                        result["evidence"],
                        ensure_ascii=False,
                    ),
                "overlap_exclusions_json":
                    json.dumps(
                        result["exclusions"],
                        ensure_ascii=False,
                    ),
                "csv_label_support_count":
                    result[
                        "csv_label_support_count"
                    ],
                "semantic_normalization_status":
                    "not_normalized",
                "unit_conversion_status":
                    "not_converted",
                "event_link_status":
                    (
                        "source_hint_only"
                        if event_hint
                        else "not_linked"
                    ),
            }

            if decision == "candidate":
                candidates.append(obs)
            elif decision == "review":
                reviews.append(obs)
            elif decision == "excluded_overlap":
                excluded.append(obs)

    return candidates, reviews, excluded


def extract_group5_pdf(
    path,
    identity,
    *,
    csv_vocabulary_path=None,
):
    path = Path(path)

    candidates, reviews, discovery_excluded = (
        _pdf_discover(
            path,
            identity,
            csv_vocabulary_path,
        )
    )

    accepted = []
    excluded = list(discovery_excluded)
    unresolved = []

    for row in candidates:
        (
            decision,
            status,
            reason,
        ) = _PDF_AUDIT[
            "classify_candidate"
        ](row)

        audited = {
            **row,
            "audit_decision":
                decision,
            "audit_status":
                status,
            "audit_reason":
                reason,
        }

        if decision == "accept":
            accepted.append(audited)
        elif decision == "exclude":
            excluded.append(audited)
        else:
            unresolved.append(audited)

    # Historical frozen package had zero PDF discovery-review
    # fields, but preserve them explicitly if encountered.
    for row in reviews:
        unresolved.append({
            **row,
            "audit_decision":
                "review",
            "audit_status":
                "remaining_review",
            "audit_reason":
                "Retained from PDF discovery review population.",
        })

    measurements = []
    values = []
    issues = []

    for source in accepted:
        try:
            measurement = (
                _PDF_EXTRACT[
                    "build_measurement"
                ](source)
            )
            measurements.append(
                measurement
            )
            # Historical Group 5 writes the same structured
            # measurement rows to measurement_values.csv.
            values.append(
                dict(measurement)
            )

        except Exception as exc:
            issues.append(
                f"{source.get('report_id','')} | "
                f"{source.get('field_label_raw','')} | "
                f"{type(exc).__name__}: {exc}"
            )

    return Group5ExtractionResult(
        source_format="pdf",
        source_path=str(path),
        measurements=measurements,
        values=values,
        companion_context=[],
        excluded=excluded,
        unresolved=unresolved,
        issues=issues,
    )


def extract_group5_report(
    *,
    identity,
    csv_path=None,
    pdf_path=None,
    companion_support_path=None,
    csv_vocabulary_path=None,
):
    source_format, source_path = (
        select_group5_source(
            csv_path=csv_path,
            pdf_path=pdf_path,
        )
    )

    if source_format == "csv":
        return extract_group5_csv(
            source_path,
            identity,
            companion_support_path=
                companion_support_path,
        )

    return extract_group5_pdf(
        source_path,
        identity,
        csv_vocabulary_path=
            csv_vocabulary_path,
    )
